// Plus Two entrance chemistry bank: d- and f-block elements (Class 12). Original fibub questions.
// Data: 3d metals (Z, atom 3d/4s): Sc 21 (1,2), Ti 22 (2,2), V 23 (3,2), Cr 24 (5,1), Mn 25 (5,2), Fe 26 (6,2), Co 27 (7,2), Ni 28 (8,2), Cu 29 (10,1), Zn 30 (10,2). Spin-only mu = sqrt(n(n+2)) BM. E (V): Ti2+ -1.63, V2+ -1.18, Cr2+ -0.91, Mn2+ -1.18, Fe2+ -0.44, Co2+ -0.28, Ni2+ -0.25, Cu2+ +0.34, Zn2+ -0.76; Fe3+/Fe2+ +0.77, Cu+/Cu +0.52, Cu2+/Cu+ +0.15, Au+/Au +1.69, Au3+/Au+ +1.40. Ln3+ has 4f^(Z-57). Molar masses: KMnO4 158, K2Cr2O7 294, MnO2 87, K2MnO4 197, FeSO4 152, Fe 56, H2C2O4 90, Na2C2O4 134.
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EXM = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet', 'cuet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet', 'cuet'], 3: ['jee-main', 'neet', 'comedk', 'cuet'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const L = [];
const mkx = (level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { type: 'mcq', level, format: 'single', exams: EXM[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const mk = (...a) => { L.push(mkx(...a)); };
const nat = (level, sub, q, answer, tol, unit, sol, trap, calc) => { L.push({ type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) }); };
const msq = (level, sub, q, options, answer, sol, trap) => { L.push({ type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) }); };
const asr = (level, sub, A, R, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'assertion', exams: EXM[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) }); };
const stm = (level, sub, s1, s2, answer, sol, trap) => { L.push({ type: 'mcq', level, format: 'statements', exams: EXM[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) }); };
const mat = (level, sub, group, q, right, wrongs, sol, trap) => { L.push({ ...mkx(level, sub, q, right, wrongs, sol, trap), format: 'match', group }); };
const P = (level, sub, group, q, right, wrongs, sol, trap) => { L.push({ ...mkx(level, sub, q, right, wrongs, sol, trap), format: 'passage', group }); };
const PN = (level, sub, group, q, answer, tol, unit, sol, trap, calc) => { L.push({ type: 'nat', level, format: 'passage', exams: EX[level], sub, group, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}), ...(calc ? { calc } : {}) }); };
const l10 = Math.log10;
// ---------- Data tables ----------
const AT = [ // 3d atoms: symbol, Z, 3d electrons, 4s electrons
  { s: 'Sc', Z: 21, d: 1, e: 2 }, { s: 'Ti', Z: 22, d: 2, e: 2 }, { s: 'V', Z: 23, d: 3, e: 2 }, { s: 'Cr', Z: 24, d: 5, e: 1 }, { s: 'Mn', Z: 25, d: 5, e: 2 },
  { s: 'Fe', Z: 26, d: 6, e: 2 }, { s: 'Co', Z: 27, d: 7, e: 2 }, { s: 'Ni', Z: 28, d: 8, e: 2 }, { s: 'Cu', Z: 29, d: 10, e: 1 }, { s: 'Zn', Z: 30, d: 10, e: 2 },
];
const A = Object.fromEntries(AT.map((a) => [a.s, a]));
const cfgA = (a) => `[Ar] 3d<sup>${a.d}</sup> 4s<sup>${a.e}</sup>`;
const dOf = (a, z) => a.d + a.e - z; // d electrons of M^z+ (4s electrons leave first)
const unpD = (d) => (d <= 5 ? d : 10 - d);
const bm = (n) => +Math.sqrt(n * (n + 2)).toFixed(2);
const IONS = [ // [symbol, charge, colour in water or ''] colour '' = colourless
  ['Sc', 3, ''], ['Ti', 3, 'purple'], ['V', 3, 'green'], ['Cr', 3, 'violet'], ['Cr', 2, 'blue'], ['Mn', 2, 'pale pink'], ['Fe', 2, 'pale green'], ['Fe', 3, 'yellow-brown'],
  ['Co', 2, 'pink'], ['Ni', 2, 'green'], ['Cu', 2, 'blue'], ['Cu', 1, ''], ['Zn', 2, ''], ['Ti', 4, ''], ['Mn', 3, 'violet'],
];
const ionF = (s, z) => `${s}<sup>${z}+</sup>`;
const LN = ['La', 'Ce', 'Pr', 'Nd', 'Pm', 'Sm', 'Eu', 'Gd', 'Tb', 'Dy', 'Ho', 'Er', 'Tm', 'Yb', 'Lu'];
const f3 = (sym) => LN.indexOf(sym); // 4f electrons in Ln3+ (La = 0 ... Lu = 14)
const unpF = (n) => (n <= 7 ? n : 14 - n);
// ---------- Fixed items made from the tables ----------
for (const [s, z] of [['Ti', 3], ['Cr', 3], ['Mn', 2], ['Fe', 3], ['Co', 2], ['Ni', 2], ['Cu', 2], ['Zn', 2], ['Fe', 2], ['Cu', 1]]) {
  const a = A[s]; const d = dOf(a, z);
  nat(z === 1 || ['Cu', 'Cr'].includes(s) ? 3 : 2, 'electronic configuration of ions', `How many electrons are in the 3d subshell of ${ionF(s, z)}? (Atomic number of ${s} = ${a.Z}.)`, d, 0, '', `<p>Atom: ${cfgA(a)}. For a 3d metal the 4s electrons are lost first, then 3d.</p><p>${ionF(s, z)}: remove ${z} electron${z > 1 ? 's' : ''}: ${a.e >= z ? `all ${z} come from 4s` : `${a.e} from 4s and ${z - a.e} from 3d`}, leaving 3d<sup>${d}</sup>. Answer: <b>${d}</b>.</p>`, 'Atoms fill 4s before 3d, but ions lose 4s electrons first.', () => a.d + a.e - z);
}
for (const [s, z, mu] of [['Ti', 3], ['V', 3], ['Cr', 3], ['Mn', 2], ['Fe', 2], ['Fe', 3], ['Co', 2], ['Ni', 2], ['Cu', 2], ['Cr', 2], ['Mn', 3]]) {
  const a = A[s]; const d = dOf(a, z); const n = unpD(d); const m = bm(n);
  nat(['Ti', 'V', 'Cu', 'Ni'].includes(s) ? 2 : 3, 'magnetic moment', `Calculate the spin-only magnetic moment (in BM) of ${ionF(s, z)} (free ion, atomic number of ${s} = ${a.Z}).`, m, 0.02, 'BM', `<p>${ionF(s, z)} has 3d<sup>${d}</sup>, so n = ${n} unpaired electron${n === 1 ? '' : 's'}.</p><p>&mu; = sqrt(n(n+2)) = sqrt(${n} &times; ${n + 2}) = <b>${m} BM</b>.</p>`, 'First write the configuration of the ION, not the atom.', () => Math.sqrt(unpD(a.d + a.e - z) * (unpD(a.d + a.e - z) + 2)));
}
for (const s of ['Cr', 'Cu', 'Mn', 'Fe', 'V']) {
  const a = A[s]; const n = unpD(a.d) + (a.e === 1 ? 1 : 0);
  nat(s === 'Cr' || s === 'Cu' ? 3 : 2, 'unpaired electrons in atoms', `How many unpaired electrons are present in a ground-state atom of ${s} (Z = ${a.Z})?`, n, 0, '', `<p>Ground state of ${s}: ${cfgA(a)}${s === 'Cr' || s === 'Cu' ? ' (one 4s electron moves into 3d to give a half-filled or filled 3d subshell)' : ''}.</p><p>3d: ${unpD(a.d)} unpaired; 4s: ${a.e === 1 ? '1 unpaired' : '0 unpaired (paired)'}. Total = <b>${n}</b>.</p>`, s === 'Cr' ? 'Do not forget the single 4s electron.' : '', () => unpD(a.d) + (a.e === 1 ? 1 : 0));
}
for (const [s, z, col] of IONS.filter((_, i) => [0, 1, 3, 5, 10, 11, 12, 13].includes(i))) {
  const a = A[s]; const d = dOf(a, z); const coloured = d > 0 && d < 10;
  const Y = 'coloured, because it has partly filled d orbitals (d-d transitions)'; const N = 'colourless, because it has d<sup>0</sup> or d<sup>10</sup> (no d-d transition possible)';
  mk(2, 'colour of ions', `The aqueous ion ${ionF(s, z)} is`, coloured ? Y : N, coloured ? [N, 'colourless, because all its electrons are paired', 'coloured, because it has a vacant 4s orbital'] : [Y, 'coloured, because it has unpaired electrons', 'coloured, because of its high charge'], `<p>${ionF(s, z)} has 3d<sup>${d}</sup>. ${coloured ? `A partly filled d subshell allows d-d transitions in the visible region, so it is coloured${col ? ' (' + col + ')' : ''}.` : `d<sup>${d}</sup> has no empty d orbital to jump to (d<sup>10</sup>) or no electron to excite (d<sup>0</sup>), so it is colourless.`}</p>`, 'Colour needs a partly filled d subshell, not just unpaired electrons.');
}
const OXS = [
  ['KMnO<sub>4</sub>', 'Mn', 7, 'K is +1 and each O is -2: +1 + x - 8 = 0', 2], ['K<sub>2</sub>MnO<sub>4</sub>', 'Mn', 6, '2(+1) + x + 4(-2) = 0', 2], ['MnO<sub>2</sub>', 'Mn', 4, 'x + 2(-2) = 0', 2], ['Mn<sub>2</sub>O<sub>7</sub>', 'Mn', 7, '2x + 7(-2) = 0', 2],
  ['K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>', 'Cr', 6, '2(+1) + 2x + 7(-2) = 0', 2], ['CrO<sub>2</sub>Cl<sub>2</sub>', 'Cr', 6, 'x + 2(-2) + 2(-1) = 0', 3], ['K<sub>2</sub>FeO<sub>4</sub>', 'Fe', 6, '2(+1) + x + 4(-2) = 0', 3], ['OsO<sub>4</sub>', 'Os', 8, 'x + 4(-2) = 0', 2],
  ['V<sub>2</sub>O<sub>5</sub>', 'V', 5, '2x + 5(-2) = 0', 2], ['[VO]<sup>2+</sup> (vanadyl)', 'V', 4, 'x + (-2) = +2', 3], ['Na<sub>2</sub>CrO<sub>4</sub>', 'Cr', 6, '2(+1) + x + 4(-2) = 0', 2], ['TiO<sub>2</sub>', 'Ti', 4, 'x + 2(-2) = 0', 1],
];
for (const [f, m, ox, eq, lv] of OXS) nat(lv, 'oxidation state', `Find the oxidation state of ${m} in ${f}.`, ox, 0, '', `<p>Set the sum of oxidation states to the overall charge: ${eq}.</p><p>So the oxidation state of ${m} is <b>+${ox}</b>.</p>`, '', () => ox);
for (const s of ['Nd', 'Sm', 'Eu', 'Gd', 'Dy', 'Er', 'Yb']) {
  const n = f3(s); const u = unpF(n);
  nat(['Nd', 'Sm', 'Gd'].includes(s) ? 3 : 4, 'lanthanoid ions', `How many unpaired 4f electrons does ${s}<sup>3+</sup> have? (Atomic number of ${s}: ${57 + n}; use Hund&rsquo;s rule for the 4f<sup>${n}</sup> ion.)`, u, 0, '', `<p>${s}<sup>3+</sup> = [Xe] 4f<sup>${n}</sup> (the 6s and 5d electrons are lost). Seven 4f orbitals: electrons fill singly first up to 7, then pair.</p><p>${n} &le; 7: ${n <= 7 ? `all ${n} unpaired` : `7 singly + ${n - 7} paired = 14 - ${n}`}. Unpaired = <b>${u}</b>.</p>`, 'Count 4f electrons as (atomic number - 57) for Ln<sup>3+</sup>.', () => (57 + f3(s) - 57 <= 7 ? f3(s) : 14 - f3(s)));
}
// ---------- Configurations (hand-written) ----------
mk(1, 'electronic configuration', 'The ground-state electronic configuration of chromium (Z = 24) is', '[Ar] 3d<sup>5</sup> 4s<sup>1</sup>', ['[Ar] 3d<sup>4</sup> 4s<sup>2</sup>', '[Ar] 3d<sup>6</sup>', '[Ar] 4s<sup>2</sup> 4p<sup>4</sup>'], '<p>Chromium is an exception: moving one 4s electron into 3d gives a half-filled 3d<sup>5</sup> subshell, which is extra stable because of exchange energy and symmetry. The regular 3d<sup>4</sup>4s<sup>2</sup> is therefore not the ground state.</p>');
mk(1, 'electronic configuration', 'Copper (Z = 29) has the configuration', '[Ar] 3d<sup>10</sup> 4s<sup>1</sup>', ['[Ar] 3d<sup>9</sup> 4s<sup>2</sup>', '[Ar] 3d<sup>8</sup> 4s<sup>2</sup> 4p<sup>1</sup>', '[Ar] 3d<sup>10</sup>'], '<p>A completely filled 3d<sup>10</sup> subshell is more stable, so one 4s electron moves into 3d. This is the second exception in the 3d series (the first is Cr).</p>');
mk(1, 'general configuration', 'The general outer electronic configuration of d-block elements is', '(n-1)d<sup>1-10</sup> ns<sup>1-2</sup>', ['(n-2)f<sup>1-14</sup> (n-1)d<sup>0-1</sup> ns<sup>2</sup>', 'ns<sup>2</sup> np<sup>1-6</sup>', '(n-1)d<sup>1-10</sup> ns<sup>2</sup> only'], '<p>d-block: (n-1)d<sup>1-10</sup> ns<sup>1-2</sup> (Pd is 4d<sup>10</sup>5s<sup>0</sup> as an exception). The second option is the f-block. "ns<sup>2</sup> only" fails for Cr and Cu.</p>');
mk(1, 'transition elements', 'Which of the following is NOT considered a transition element by the IUPAC definition?', 'Zn', ['Fe', 'Cu', 'Ni'], '<p>A transition element has a partly filled d subshell in the atom or in at least one common ion. Zn (3d<sup>10</sup>4s<sup>2</sup>) and Zn<sup>2+</sup> (3d<sup>10</sup>) both have full d subshells. Cu<sup>2+</sup> is d<sup>9</sup>, so copper qualifies.</p>');
mk(1, 'inner transition elements', 'In the inner transition elements the last electron enters the', '(n-2)f subshell', ['(n-1)d subshell', 'ns subshell', 'np subshell'], '<p>Lanthanoids fill 4f; actinoids fill 5f. These are the inner transition (f-block) elements.</p>');
mk(2, 'electronic configuration', 'The ion Cu<sup>+</sup> is colourless and diamagnetic because its configuration is', '[Ar] 3d<sup>10</sup>', ['[Ar] 3d<sup>9</sup>', '[Ar] 3d<sup>8</sup> 4s<sup>1</sup>', '[Ar] 3d<sup>9</sup> 4s<sup>1</sup>'], '<p>Copper loses its 4s electron first: 3d<sup>10</sup>4s<sup>1</sup> &rarr; 3d<sup>10</sup>. A filled d subshell has no unpaired electrons and no d-d transition, so Cu<sup>+</sup> compounds are colourless and diamagnetic (compare Cu<sup>2+</sup>, d<sup>9</sup>, blue).</p>');
mk(2, 'electronic configuration', 'In forming ions, the 3d-series elements lose electrons from', '4s first, and then from 3d', ['3d first, and then from 4s', '3d and 4s together in equal numbers', '4p first'], '<p>Once 3d is occupied it is lower in energy than 4s (the effective nuclear charge pulls 3d inwards), so the 4s electrons are removed first. Fe<sup>3+</sup> is [Ar]3d<sup>5</sup>, not 3d<sup>3</sup>4s<sup>2</sup>.</p>');
mk(3, 'electronic configuration', 'Which of the following elements has the electronic configuration [Kr] 4d<sup>10</sup> 5s<sup>0</sup>?', 'Pd', ['Ag', 'Cd', 'Rh'], '<p>Palladium (Z = 46) is the exception with 4d<sup>10</sup> and no 5s electron. Ag is 4d<sup>10</sup>5s<sup>1</sup>; Cd is 4d<sup>10</sup>5s<sup>2</sup>; Rh is 4d<sup>8</sup>5s<sup>1</sup>.</p>', 'Pd is the only element whose outer s subshell is empty in the ground state.');
mk(3, 'electronic configuration', 'The configuration of gadolinium (Z = 64) is [Xe] 4f<sup>7</sup> 5d<sup>1</sup> 6s<sup>2</sup> rather than 4f<sup>8</sup> 6s<sup>2</sup> because', 'the half-filled 4f<sup>7</sup> subshell is extra stable', ['5d is lower in energy than 4f in all lanthanoids', 'Gd<sup>3+</sup> must have a 5d electron', 'the 6s electrons are lost first'], '<p>As with Cr (3d<sup>5</sup>4s<sup>1</sup>), a half-filled f<sup>7</sup> subshell gains stability from exchange energy, so one electron goes into 5d. The same reason gives Lu its 4f<sup>14</sup>5d<sup>1</sup> configuration (filled 4f).</p>');
mk(3, 'unpaired electrons', 'Among the ground-state atoms of Mn, Fe, Cr and V, the one with the maximum number of unpaired electrons is', 'Cr', ['Mn', 'Fe', 'V'], '<p>Cr: 3d<sup>5</sup>4s<sup>1</sup> has 6 unpaired electrons. Mn: 3d<sup>5</sup>4s<sup>2</sup> has 5. Fe: 4. V: 3. Chromium has the most of any element in the 3d series.</p>', 'Do not forget that the single 4s electron of Cr is also unpaired.');
mk(4, 'electronic configuration', 'Which pair has the same number of unpaired electrons in the ground state?', 'Cr (Z = 24) and Mo (Z = 42)', ['Cr and Mn', 'Cu and Zn', 'Fe and Mn'], '<p>Cr: 3d<sup>5</sup>4s<sup>1</sup>, 6 unpaired. Mo: 4d<sup>5</sup>5s<sup>1</sup>, 6 unpaired (same group, same exception). Mn has 5, Cu 1, Zn 0, Fe 4.</p>', 'Cr and Mo are both exceptions of the same kind.');
mk(4, 'electronic configuration', 'The 3d<sup>5</sup> configuration of Mn<sup>2+</sup> makes Mn<sup>3+</sup> a strong oxidising agent because', 'reduction of Mn<sup>3+</sup> to Mn<sup>2+</sup> gives the stable half-filled d<sup>5</sup> ion', ['Mn<sup>3+</sup> has a half-filled d subshell', 'Mn<sup>2+</sup> has a filled d subshell', 'Mn<sup>3+</sup> has no unpaired electrons'], '<p>Mn<sup>3+</sup> is d<sup>4</sup>; gaining an electron makes d<sup>5</sup> (half-filled), which is a stable arrangement. E&deg;(Mn<sup>3+</sup>/Mn<sup>2+</sup>) = +1.57 V is the highest in the series for this reason.</p>');
// ---------- Trends ----------
mk(1, 'atomic size', 'Across the 3d series from Sc to Zn the atomic radii', 'first decrease, then stay nearly constant, and increase slightly at the end', ['increase steadily', 'decrease steadily', 'remain exactly constant'], '<p>Nuclear charge rises, but extra electrons enter the inner 3d subshell and shield the 4s electrons. In the middle the two effects balance (radii nearly constant). At Cu and Zn, d-d repulsion in the filled d subshell expands the atom slightly.</p>');
mk(2, 'atomic size', 'The atomic radii of 3d metals from Cr to Cu are nearly the same because', 'the shielding of the 4s electrons by added 3d electrons balances the increase in nuclear charge', ['4s electrons are lost completely', 'the nuclear charge does not change', 'd electrons do not shield at all'], '<p>Each new proton is balanced by a new 3d electron placed inside the 4s shell, so the effective nuclear charge felt by the 4s electrons increases only slowly.</p>');
mk(2, 'melting points', 'Transition metals have high melting points because', 'both ns and (n-1)d unpaired electrons take part in strong metallic bonding', ['they have only ns electrons for bonding', 'they have very large atomic radii', 'they form ionic lattices'], '<p>More unpaired d electrons mean more electrons shared in the metallic bond: stronger bonding, higher melting point and enthalpy of atomisation. The maximum is near the middle of each series (Cr, Mo, W).</p>');
mk(2, 'melting points', 'Zn, Cd and Hg have unusually low melting points among the d-block because', 'their d subshell is completely filled and does not take part in metallic bonding', ['they are not metals', 'they have no s electrons', 'they have the highest atomic masses'], '<p>With d<sup>10</sup> there are no unpaired d electrons, so only the two ns electrons form the metallic bond. Hg is liquid at room temperature.</p>');
mk(2, 'enthalpy of atomisation', 'Which 3d metal has the lowest enthalpy of atomisation?', 'Zn', ['Ti', 'V', 'Cr'], '<p>Zn has no unpaired d electrons (3d<sup>10</sup>), so metallic bonding is weak: about 130 kJ/mol. The strong bonds of Ti, V (about 470-515 kJ/mol) come from partly filled d orbitals.</p>');
mk(3, 'density', 'The densities of the 3d metals increase from Ti to Cu because', 'the increase in atomic mass is larger than the increase in volume (radii change little)', ['the atomic radii increase greatly', 'the number of s electrons increases', 'the metals become less closely packed'], '<p>Density = mass/volume. Atomic masses increase steadily, while the atomic volume is almost constant (or even falls), so density rises. Zn is slightly lower than Cu because of its larger volume.</p>');
mk(4, 'ionisation enthalpy', 'The first ionisation enthalpies of the 3d metals', 'increase only slightly from Ti to Zn, with an irregular pattern', ['decrease sharply across the series', 'increase sharply as for the main group', 'are all the same'], '<p>Extra nuclear charge is mostly cancelled by d-electron shielding, so &Delta;<sub>i</sub>H<sub>1</sub> increases slowly (about 650 to 760 kJ/mol; Zn is highest at 906 because of the filled 3d and 4s subshells).</p>');
mk(4, 'ionisation enthalpy', 'The second ionisation enthalpy of Cr and Cu is unusually high because', 'Cr<sup>+</sup> (3d<sup>5</sup>) and Cu<sup>+</sup> (3d<sup>10</sup>) have stable configurations that are hard to disturb', ['Cr and Cu have no 4s electrons', 'they have the smallest radii in the series', 'their second electron is removed from 4p'], '<p>The second electron must come from a half-filled (Cr<sup>+</sup>) or filled (Cu<sup>+</sup>) 3d subshell, which takes extra energy. Cu has the highest &Delta;<sub>i</sub>H<sub>2</sub> (1958 kJ/mol) in the series.</p>');
mk(4, 'ionisation enthalpy', 'The third ionisation enthalpy of manganese is high (about 3250 kJ/mol) because', 'the third electron must be removed from the stable half-filled Mn<sup>2+</sup> (3d<sup>5</sup>)', ['Mn is the smallest 3d atom', 'Mn<sup>2+</sup> has a filled 4s orbital', 'Mn has one unpaired electron'], '<p>Mn<sup>2+</sup> is 3d<sup>5</sup>, a stable half-filled arrangement. Removing another electron is hard, so Mn(II) is much more stable than Mn(III).</p>');
mk(4, 'standard electrode potentials', 'E&deg;(Cu<sup>2+</sup>/Cu) is positive (+0.34 V), unlike other 3d metals, because', 'the energy to atomise and ionise Cu is not compensated by the hydration enthalpy of Cu<sup>2+</sup>', ['copper has no 4s electron', 'Cu<sup>2+</sup> has a half-filled d subshell', 'copper is a noble gas'], '<p>E&deg; depends on sublimation, ionisation and hydration enthalpies. For Cu the sum of atomisation and the first two ionisation enthalpies (large because of the stable d<sup>10</sup> Cu<sup>+</sup>) outweighs the hydration enthalpy of Cu<sup>2+</sup>, so Cu does not displace H<sub>2</sub> from acids.</p>');
mk(4, 'standard electrode potentials', 'The E&deg; values of Mn<sup>2+</sup>/Mn (-1.18 V) and Zn<sup>2+</sup>/Zn (-0.76 V) are more negative than the general trend because', 'Mn<sup>2+</sup> (d<sup>5</sup>) and Zn<sup>2+</sup> (d<sup>10</sup>) have extra-stable configurations', ['the atoms have partly filled d orbitals', 'these ions are the smallest', 'hydration enthalpy is zero for both'], '<p>The stability of half-filled d<sup>5</sup> and filled d<sup>10</sup> makes the oxidation M &rarr; M<sup>2+</sup> easier, so E&deg; is more negative than the smooth trend would give.</p>');
mk(4, 'standard electrode potentials', 'E&deg;(Cr<sup>3+</sup>/Cr<sup>2+</sup>) = -0.41 V is negative while E&deg;(Mn<sup>3+</sup>/Mn<sup>2+</sup>) = +1.57 V is highly positive. This shows that', 'Cr<sup>3+</sup> (d<sup>3</sup>, t<sub>2g</sub><sup>3</sup>) is stable and Cr<sup>2+</sup> is a reducing agent, while Mn<sup>3+</sup> readily becomes d<sup>5</sup> Mn<sup>2+</sup>', ['Cr<sup>2+</sup> is stable and Cr<sup>3+</sup> is a strong oxidising agent', 'Mn<sup>3+</sup> is more stable than Mn<sup>2+</sup>', 'both couples have the same stable ion'], '<p>Negative E&deg; for Cr<sup>3+</sup>/Cr<sup>2+</sup> means Cr<sup>3+</sup> is hard to reduce, so Cr<sup>2+</sup> is a good reducing agent. Positive E&deg; for Mn<sup>3+</sup>/Mn<sup>2+</sup> means Mn<sup>3+</sup> is a strong oxidising agent.</p>');
mk(3, 'trends in oxidation states', 'The highest oxidation state shown by an element of the 3d series from Sc to Mn is equal to', 'the total number of 4s and 3d electrons', ['the number of 4s electrons', 'the number of 3d electrons only', 'the group number minus 10'], '<p>Sc +3, Ti +4, V +5, Cr +6, Mn +7: (n-1)d and ns electrons are all available. After Mn the highest state falls (Fe +6 rare, Co +5 rare), because d orbitals are held more tightly.</p>');
// ---------- Oxidation states ----------
mk(1, 'oxidation states', 'The most common oxidation state of the 3d metals (excluding Sc) is', '+2', ['+1', '+3', '+7'], '<p>The two 4s electrons are lost most easily, giving +2. Scandium is +3 and Zn is +2 only.</p>');
mk(2, 'oxidation states', 'The element of the 3d series that shows the highest oxidation state (+7) is', 'Mn', ['Cr', 'Fe', 'V'], '<p>Mn: 3d<sup>5</sup>4s<sup>2</sup> gives all seven electrons: MnO<sub>4</sub><sup>-</sup>, Mn<sub>2</sub>O<sub>7</sub>. Cr reaches +6.</p>');
mk(2, 'oxidation states', 'The highest fluoride of manganese is MnF<sub>4</sub> but its highest oxide is Mn<sub>2</sub>O<sub>7</sub>. The reason is that', 'oxygen can form multiple (p&pi;-d&pi;) bonds with Mn, stabilising the +7 state, while fluorine cannot', ['oxygen is less electronegative than fluorine', 'fluorine forms bonds only with s block elements', 'Mn<sub>2</sub>O<sub>7</sub> contains Mn in +4 state'], '<p>Oxygen can bond through double bonds (Mn=O), so it supports very high oxidation states (+7). Fluorine forms only single bonds, so MnF<sub>7</sub> would be too crowded and unstable; the highest fluoride is MnF<sub>4</sub>.</p>');
mk(2, 'oxidation states', 'Which of the following statements about oxidation states is correct?', 'In the d-block, oxidation states in a series usually differ by one unit (e.g. Mn(II) to Mn(VII)), unlike the p-block where they differ by two', ['The d-block oxidation states always differ by two', 'All d-block elements show only one oxidation state', 'Variable oxidation state is seen only in the s-block'], '<p>Since (n-1)d and ns electrons have comparable energy, successive electrons can be removed one at a time: Mn +2, +3, +4, +5, +6, +7. In the p-block the states generally change by two (inert pair effect: Sn(II)/Sn(IV)).</p>');
mk(2, 'oxidation states', 'Scandium shows only the +3 state in its compounds because', 'Sc<sup>3+</sup> has a noble gas configuration (3d<sup>0</sup>), which is very stable', ['Sc has no 4s electrons', 'Sc<sup>3+</sup> has a half-filled 3d subshell', 'Sc is a non-metal'], '<p>Sc: 3d<sup>1</sup>4s<sup>2</sup>. Losing all three gives [Ar], so no other oxidation state is useful.</p>');
mk(2, 'oxidation states', 'The oxidation state of Fe in K<sub>2</sub>FeO<sub>4</sub> (potassium ferrate) is', '+6', ['+4', '+2', '+8'], '<p>2(+1) + x + 4(-2) = 0, so x = +6. Fe<sup>6+</sup> is a very strong oxidant.</p>');
mk(2, 'oxidation states', 'In which compound does the transition metal have the highest oxidation state?', 'OsO<sub>4</sub>', ['K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>', 'KMnO<sub>4</sub>', 'V<sub>2</sub>O<sub>5</sub>'], '<p>Os is +8 in OsO<sub>4</sub>; Mn +7; Cr +6; V +5. (RuO<sub>4</sub> also shows +8.)</p>', 'Group number is the guide: Os is in group 8.');
// ---------- Magnetic, colour, catalysis, interstitial, alloys ----------
mk(1, 'magnetic properties', 'A substance that is attracted by a magnetic field because of unpaired electrons is called', 'paramagnetic', ['diamagnetic', 'ferrimagnetic only', 'non-magnetic'], '<p>Unpaired electrons give permanent magnetic moments, so the substance is drawn into the field: paramagnetic. Diamagnetic substances (all electrons paired) are weakly repelled.</p>');
mk(2, 'magnetic properties', 'Which of the following ions is diamagnetic?', 'Zn<sup>2+</sup>', ['Fe<sup>2+</sup>', 'Cu<sup>2+</sup>', 'Mn<sup>2+</sup>'], '<p>Zn<sup>2+</sup> is 3d<sup>10</sup>, all paired. Fe<sup>2+</sup> (d<sup>6</sup>, 4 unpaired), Cu<sup>2+</sup> (d<sup>9</sup>, 1) and Mn<sup>2+</sup> (d<sup>5</sup>, 5) are paramagnetic.</p>');
mk(2, 'magnetic properties', 'The magnetic moment of a first-row transition metal ion is observed to be 3.87 BM (spin-only). The ion could be', 'Cr<sup>3+</sup> or Co<sup>2+</sup> (high spin)', ['Fe<sup>3+</sup> or Mn<sup>2+</sup>', 'Ni<sup>2+</sup> or V<sup>3+</sup>', 'Cu<sup>2+</sup> or Ti<sup>3+</sup>'], '<p>&mu; = 3.87 BM means 3 unpaired electrons (sqrt15). Cr<sup>3+</sup> is d<sup>3</sup>; high-spin Co<sup>2+</sup> is d<sup>7</sup>. Fe<sup>3+</sup>, Mn<sup>2+</sup> have 5 (5.92 BM); Ni<sup>2+</sup>, V<sup>3+</sup> have 2 (2.83); Cu<sup>2+</sup>, Ti<sup>3+</sup> have 1 (1.73).</p>');
mk(4, 'magnetic properties', 'The spin-only formula does not work well for Ln<sup>3+</sup> ions (except Gd<sup>3+</sup>, La<sup>3+</sup>, Lu<sup>3+</sup>) because', 'orbital angular momentum of the 4f electrons contributes significantly', ['4f electrons are always paired', '4f electrons are strongly shielded so there is no magnetic moment', 'lanthanoid ions are diamagnetic'], '<p>The 4f electrons are deep inside the atom, so the crystal field does not quench their orbital motion. The orbital contribution adds to the spin part, and the observed moment differs from sqrt(n(n+2)).</p>');
mk(2, 'colour', 'Transition metal ions are generally coloured because of', 'd-d transitions: electrons absorb visible light to move between split d orbitals', ['transfer of s electrons to the nucleus', 'high ionisation enthalpy', 'the presence of vacant 4p orbitals only'], '<p>In a ligand field the d orbitals split. Light of energy equal to the gap is absorbed, and the complementary colour is seen.</p>');
mk(3, 'colour', 'KMnO<sub>4</sub> is intensely purple although Mn in it has the 3d<sup>0</sup> configuration. The colour is due to', 'charge transfer from oxygen to Mn (ligand to metal charge transfer)', ['d-d transition', 'f-f transition', 'unpaired electrons in 4s'], '<p>Mn(VII) is d<sup>0</sup>, so no d-d transition is possible. The colour comes from an electron moving from O 2p (ligand) to an empty Mn d orbital by absorbing visible light. The same effect gives yellow CrO<sub>4</sub><sup>2-</sup> and orange Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>.</p>', 'd<sup>0</sup> does not mean colourless if charge transfer is possible.');
mk(3, 'colour', 'Mn<sup>2+</sup> compounds are only very pale pink, whereas Cr<sup>2+</sup> and Cu<sup>2+</sup> solutions are distinctly coloured, mainly because', 'the d-d transitions in high-spin d<sup>5</sup> are spin-forbidden and so very weak', ['Mn<sup>2+</sup> has no d electrons', 'Mn<sup>2+</sup> has a filled d subshell', 'Mn<sup>2+</sup> is a main-group ion'], '<p>In high-spin d<sup>5</sup> all five d orbitals hold one electron of the same spin. Moving an electron to another d orbital would require a spin flip, which is forbidden by the selection rule, so absorption is very weak.</p>');
mk(2, 'catalytic property', 'V<sub>2</sub>O<sub>5</sub> is used as the catalyst in', 'the contact process for sulphuric acid', ['the Haber process', 'hydrogenation of oils', 'the Ostwald process'], '<p>V<sub>2</sub>O<sub>5</sub> catalyses SO<sub>2</sub> + &frac12;O<sub>2</sub> &rarr; SO<sub>3</sub>. Haber uses Fe; hydrogenation uses finely divided Ni; Ostwald uses Pt-Rh gauze.</p>');
mk(2, 'catalytic property', 'The catalytic activity of transition metals is attributed to', 'variable oxidation states and the ability to adsorb reactants on the surface', ['their high melting points', 'their paramagnetism alone', 'their large atomic size'], '<p>They can form intermediates by changing oxidation state (e.g. V<sub>2</sub>O<sub>5</sub> to VO<sub>2</sub> to V<sub>2</sub>O<sub>5</sub>) and use free valencies on the surface to hold and activate reactant molecules.</p>');
mat(3, 'catalysts', 'm1', 'Match each catalyst (List I) with the process (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-s, B-q, C-r, D-p'], '<p>Fe catalyses ammonia synthesis (Haber). V<sub>2</sub>O<sub>5</sub> the contact process. Ni hydrogenation of vegetable oils. MnO<sub>2</sub> speeds up the decomposition of KClO<sub>3</sub>.</p>');
mk(3, 'interstitial compounds', 'Interstitial compounds of transition metals such as TiC and Fe<sub>3</sub>H are', 'hard, with high melting points, and conduct electricity like the parent metal', ['soft, ionic and brittle', 'chemically very reactive and with low melting points', 'insulators with a fixed formula'], '<p>Small atoms (H, C, N, B) sit in the voids of the metal lattice. This makes the lattice more rigid and hard, raises the melting point (TiC melts at about 3200 &deg;C), and keeps metallic conduction. They are non-stoichiometric and chemically inert.</p>');
mk(3, 'interstitial compounds', 'Which of the following is NOT a characteristic of interstitial compounds?', 'They have an exact stoichiometric formula such as TiC<sub>2</sub>', ['They are generally non-stoichiometric', 'They are chemically inert', 'They are harder than the pure metal'], '<p>Interstitial compounds are non-stoichiometric (for example TiH<sub>1.7</sub>, VH<sub>0.56</sub>); the other three statements are true.</p>');
mk(2, 'alloys', 'Brass and bronze are alloys of copper with', 'zinc and tin respectively', ['tin and zinc respectively', 'nickel and zinc respectively', 'lead and tin respectively'], '<p>Brass = Cu + Zn (about 60:40). Bronze = Cu + Sn (about 90:10).</p>');
mk(3, 'alloys', 'Transition metals form alloys readily because', 'their atomic radii are similar (within about 15%), so one metal can replace another in the lattice', ['they all have the same number of electrons', 'they are all liquid', 'they have very different sizes'], '<p>An alloy is a solid solution. When the radii differ by less than about 15%, atoms of one metal can substitute for the other in the same crystal lattice.</p>');
mk(3, 'alloys', 'Misch metal, an alloy used for lighter flints and in Mg-based alloys, consists mainly of', 'lanthanoid metals (about 95%) with iron (about 5%)', ['actinoid metals with iron', 'copper and zinc', 'nickel and chromium'], '<p>Misch metal: about 95% lanthanoids (mostly Ce, La, Nd) and about 5% iron, with traces of S, C, Ca and Al. It is used in Mg alloys for bullets, shells and lighter flints.</p>');
// ---------- Potassium permanganate ----------
mk(1, 'KMnO4 preparation', 'The starting material for the preparation of potassium permanganate is', 'pyrolusite, MnO<sub>2</sub>', ['haematite, Fe<sub>2</sub>O<sub>3</sub>', 'chromite, FeCr<sub>2</sub>O<sub>4</sub>', 'cinnabar, HgS'], '<p>MnO<sub>2</sub> is fused with KOH in air (or with KNO<sub>3</sub>) to give green K<sub>2</sub>MnO<sub>4</sub>, which is then oxidised to KMnO<sub>4</sub>.</p>');
mk(2, 'KMnO4 preparation', 'When MnO<sub>2</sub> is fused with KOH in the presence of air, the product is', 'K<sub>2</sub>MnO<sub>4</sub>, a dark green compound', ['KMnO<sub>4</sub>, a purple compound', 'Mn<sub>2</sub>O<sub>3</sub>', 'MnSO<sub>4</sub>'], '<p>2MnO<sub>2</sub> + 4KOH + O<sub>2</sub> &rarr; 2K<sub>2</sub>MnO<sub>4</sub> + 2H<sub>2</sub>O. Potassium manganate(VI) is green. It is then oxidised electrolytically or by disproportionation in acid to give permanganate.</p>');
mk(3, 'KMnO4 preparation', 'The manganate ion disproportionates in acidic or neutral solution as 3MnO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> &rarr; 2MnO<sub>4</sub><sup>-</sup> + MnO<sub>2</sub> + 2H<sub>2</sub>O. The oxidation states of Mn in the three species are', '+6, +7 and +4', ['+7, +6 and +4', '+6, +4 and +7', '+7, +4 and +6'], '<p>MnO<sub>4</sub><sup>2-</sup>: +6; MnO<sub>4</sub><sup>-</sup>: +7; MnO<sub>2</sub>: +4. Mn(VI) is both oxidised (to +7) and reduced (to +4): disproportionation.</p>');
mk(3, 'KMnO4 preparation', 'In the electrolytic oxidation of K<sub>2</sub>MnO<sub>4</sub> in alkaline solution to KMnO<sub>4</sub>, the reaction at the anode is', 'MnO<sub>4</sub><sup>2-</sup> &rarr; MnO<sub>4</sub><sup>-</sup> + e<sup>-</sup>', ['MnO<sub>4</sub><sup>-</sup> + e<sup>-</sup> &rarr; MnO<sub>4</sub><sup>2-</sup>', '2H<sub>2</sub>O + 2e<sup>-</sup> &rarr; H<sub>2</sub> + 2OH<sup>-</sup>', 'MnO<sub>2</sub> + 2e<sup>-</sup> &rarr; Mn'], '<p>Oxidation occurs at the anode: green manganate loses one electron to become purple permanganate. Hydrogen is released at the cathode (the second option).</p>');
mk(2, 'KMnO4 structure', 'The permanganate ion MnO<sub>4</sub><sup>-</sup> has the shape and magnetic behaviour', 'tetrahedral and diamagnetic', ['square planar and paramagnetic', 'tetrahedral and paramagnetic', 'octahedral and diamagnetic'], '<p>Mn(VII) is 3d<sup>0</sup> with four oxygen atoms around it in a tetrahedral arrangement. With no d electrons it is diamagnetic.</p>');
mk(2, 'KMnO4 structure', 'Which statement about MnO<sub>4</sub><sup>2-</sup> (manganate) is correct?', 'It is tetrahedral and paramagnetic with one unpaired electron', ['It is tetrahedral and diamagnetic', 'It is square planar with two unpaired electrons', 'It is octahedral with no unpaired electrons'], '<p>Mn(VI) is 3d<sup>1</sup>: one unpaired electron, &mu; = 1.73 BM. The ion is tetrahedral and green. MnO<sub>4</sub><sup>-</sup> is d<sup>0</sup>, diamagnetic.</p>');
mk(2, 'KMnO4 structure', 'In the MnO<sub>4</sub><sup>-</sup> ion the bonding between Mn and O is best described as', 'sigma bonds plus p&pi;-d&pi; bonds (oxygen p to manganese d)', ['sigma bonds only', 'ionic bonds', 'p&pi;-p&pi; bonds only'], '<p>Mn has no d electrons, but its empty d orbitals overlap sideways with filled O 2p orbitals to form p&pi;-d&pi; bonds in addition to the sigma bonds, giving partial double bond character.</p>');
mk(2, 'KMnO4 reactions', 'In acidic medium MnO<sub>4</sub><sup>-</sup> is reduced to', 'Mn<sup>2+</sup> (colourless to faint pink)', ['MnO<sub>2</sub>', 'MnO<sub>4</sub><sup>2-</sup>', 'Mn<sub>2</sub>O<sub>7</sub>'], '<p>MnO<sub>4</sub><sup>-</sup> + 8H<sup>+</sup> + 5e<sup>-</sup> &rarr; Mn<sup>2+</sup> + 4H<sub>2</sub>O. The purple colour disappears, so permanganate acts as its own indicator in titrations.</p>');
mk(3, 'KMnO4 reactions', 'Permanganate is reduced to MnO<sub>2</sub> in neutral or weakly alkaline solution. The number of electrons gained per MnO<sub>4</sub><sup>-</sup> is', '3', ['5', '1', '6'], '<p>MnO<sub>4</sub><sup>-</sup> + 2H<sub>2</sub>O + 3e<sup>-</sup> &rarr; MnO<sub>2</sub> + 4OH<sup>-</sup>: +7 to +4, so 3 electrons. (In acid: 5; in strongly alkaline solution to MnO<sub>4</sub><sup>2-</sup>: 1.)</p>', 'Acid 5, neutral 3, strongly alkaline 1.');
mk(3, 'KMnO4 reactions', 'In acidic KMnO<sub>4</sub> titrations dilute H<sub>2</sub>SO<sub>4</sub> is used, and not HCl, because', 'HCl is oxidised by KMnO<sub>4</sub> to chlorine, consuming extra oxidant', ['H<sub>2</sub>SO<sub>4</sub> is a stronger oxidising agent', 'HCl precipitates MnO<sub>2</sub>', 'HCl is volatile and evaporates'], '<p>MnO<sub>4</sub><sup>-</sup> oxidises Cl<sup>-</sup> to Cl<sub>2</sub>: 2MnO<sub>4</sub><sup>-</sup> + 16H<sup>+</sup> + 10Cl<sup>-</sup> &rarr; 2Mn<sup>2+</sup> + 5Cl<sub>2</sub> + 8H<sub>2</sub>O, which makes the titre too high. HNO<sub>3</sub> is itself an oxidising agent, so dilute H<sub>2</sub>SO<sub>4</sub> is chosen.</p>', 'Sulphate is the only common anion that is stable to permanganate.');
mk(3, 'KMnO4 reactions', 'The balanced reaction of acidic permanganate with ferrous ion is', 'MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; Mn<sup>2+</sup> + 5Fe<sup>3+</sup> + 4H<sub>2</sub>O', ['MnO<sub>4</sub><sup>-</sup> + Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; Mn<sup>2+</sup> + Fe<sup>3+</sup> + 4H<sub>2</sub>O', 'MnO<sub>4</sub><sup>-</sup> + 3Fe<sup>2+</sup> + 4H<sup>+</sup> &rarr; MnO<sub>2</sub> + 3Fe<sup>3+</sup> + 2H<sub>2</sub>O', '2MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> + 16H<sup>+</sup> &rarr; 2Mn<sup>2+</sup> + 5Fe<sup>3+</sup> + 8H<sub>2</sub>O'], '<p>Mn gains 5 electrons; each Fe<sup>2+</sup> loses 1, so 5 Fe<sup>2+</sup> are needed. Balance O with 4H<sub>2</sub>O and H with 8H<sup>+</sup>. The first option has no electron balance (5 e gained, 1 lost); the second is the MnO<sub>2</sub> (neutral medium) path; the third gains 10 electrons but loses only 5.</p>', 'Check charge: left 1(-1) + 5(+2) + 8(+1) = +17; right 2 + 15 = +17.');
mk(3, 'KMnO4 reactions', 'In acidic medium oxalate is oxidised by permanganate: 2MnO<sub>4</sub><sup>-</sup> + 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup> + 16H<sup>+</sup> &rarr; 2Mn<sup>2+</sup> + 10CO<sub>2</sub> + 8H<sub>2</sub>O. The reaction is slow at first and speeds up because', 'Mn<sup>2+</sup> formed acts as an autocatalyst', ['CO<sub>2</sub> escapes from the solution', 'oxalate is regenerated', 'water is produced'], '<p>The titration is done at about 60-70 &deg;C. The first drops are decolourised slowly; the Mn<sup>2+</sup> produced catalyses the reaction (autocatalysis), and afterwards the colour disappears at once.</p>');
mk(3, 'KMnO4 reactions', 'When heated at 513 K, potassium permanganate gives', 'K<sub>2</sub>MnO<sub>4</sub>, MnO<sub>2</sub> and O<sub>2</sub>', ['K<sub>2</sub>O, Mn<sub>2</sub>O<sub>7</sub> and O<sub>2</sub>', 'KMnO<sub>2</sub> and O<sub>2</sub>', 'MnO and K<sub>2</sub>O only'], '<p>2KMnO<sub>4</sub> &rarr; K<sub>2</sub>MnO<sub>4</sub> + MnO<sub>2</sub> + O<sub>2</sub>. This is also the laboratory route to a small amount of oxygen.</p>');
mk(3, 'KMnO4 reactions', 'KMnO<sub>4</sub> reacts with iodide in neutral or alkaline medium to give', 'iodate (IO<sub>3</sub><sup>-</sup>), with MnO<sub>2</sub>', ['I<sub>2</sub>, with Mn<sup>2+</sup>', 'IO<sub>4</sub><sup>-</sup>, with Mn<sup>2+</sup>', 'HI and MnO<sub>4</sub><sup>2-</sup>'], '<p>2MnO<sub>4</sub><sup>-</sup> + H<sub>2</sub>O + I<sup>-</sup> &rarr; 2MnO<sub>2</sub> + 2OH<sup>-</sup> + IO<sub>3</sub><sup>-</sup>. In acid the product is I<sub>2</sub> (and Mn<sup>2+</sup>). The medium decides the products.</p>');
mk(4, 'KMnO4 reactions', 'Which of the following is NOT oxidised by acidified KMnO<sub>4</sub>?', 'SO<sub>4</sub><sup>2-</sup>', ['H<sub>2</sub>S', 'SO<sub>2</sub>', 'NO<sub>2</sub><sup>-</sup>'], '<p>Sulphate has sulphur in its highest oxidation state (+6), so it cannot be oxidised. H<sub>2</sub>S gives S, SO<sub>2</sub> gives SO<sub>4</sub><sup>2-</sup>, NO<sub>2</sub><sup>-</sup> gives NO<sub>3</sub><sup>-</sup>.</p>');
mk(4, 'KMnO4 reactions', 'Cold dilute alkaline KMnO<sub>4</sub> (Baeyer&rsquo;s reagent) converts ethene into', 'ethane-1,2-diol, with the purple colour changing to brown MnO<sub>2</sub>', ['ethanal', 'ethanoic acid with CO<sub>2</sub>', 'ethanol'], '<p>Cold, dilute, alkaline permanganate adds two OH groups across the double bond (syn-hydroxylation) and is reduced to brown MnO<sub>2</sub>. It is used as a test for unsaturation.</p>');
mk(4, 'KMnO4 reactions', 'When KMnO<sub>4</sub> is treated with concentrated H<sub>2</sub>SO<sub>4</sub>, a dark green explosive oil forms. It is', 'Mn<sub>2</sub>O<sub>7</sub>', ['MnSO<sub>4</sub>', 'MnO<sub>2</sub>', 'K<sub>2</sub>MnO<sub>4</sub>'], '<p>2KMnO<sub>4</sub> + H<sub>2</sub>SO<sub>4</sub>(conc.) &rarr; Mn<sub>2</sub>O<sub>7</sub> + K<sub>2</sub>SO<sub>4</sub> + H<sub>2</sub>O. Mn<sub>2</sub>O<sub>7</sub> is a very powerful, explosive oxidant (Mn(VII), acidic oxide).</p>');
mk(4, 'KMnO4 reactions', 'In which medium does MnO<sub>4</sub><sup>-</sup> have the smallest equivalent mass (molar mass M)?', 'strongly acidic (M/5)', ['neutral (M/3)', 'strongly alkaline (M/1)', 'all the same'], '<p>Equivalent mass = M/(electrons gained). Acid: 5 electrons, M/5 = 31.6. Neutral: M/3 = 52.7. Strongly alkaline: M = 158. Smaller equivalent mass means more electrons per formula unit.</p>');
// ---------- Potassium dichromate ----------
mk(1, 'K2Cr2O7 preparation', 'Potassium dichromate is prepared from the ore', 'chromite, FeCr<sub>2</sub>O<sub>4</sub>', ['pyrolusite, MnO<sub>2</sub>', 'bauxite, Al<sub>2</sub>O<sub>3</sub>', 'galena, PbS'], '<p>Chromite is fused with sodium carbonate in excess air to give sodium chromate, which is acidified to sodium dichromate and then converted to potassium dichromate.</p>');
mk(2, 'K2Cr2O7 preparation', 'The fusion of chromite ore with Na<sub>2</sub>CO<sub>3</sub> in air gives', 'Na<sub>2</sub>CrO<sub>4</sub> (yellow) and Fe<sub>2</sub>O<sub>3</sub>', ['Na<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> directly', 'Cr<sub>2</sub>O<sub>3</sub> and FeO', 'CrCl<sub>3</sub>'], '<p>4FeCr<sub>2</sub>O<sub>4</sub> + 8Na<sub>2</sub>CO<sub>3</sub> + 7O<sub>2</sub> &rarr; 8Na<sub>2</sub>CrO<sub>4</sub> + 2Fe<sub>2</sub>O<sub>3</sub> + 8CO<sub>2</sub>. Here both Cr (+3 to +6) and Fe (+2 to +3) are oxidised. The chromate is leached with water, leaving iron(III) oxide behind.</p>');
mk(3, 'K2Cr2O7 preparation', 'Sodium dichromate is converted into potassium dichromate by adding KCl because', 'K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> is much less soluble in water and crystallises out', ['KCl is a reducing agent', 'KCl lowers the pH', 'sodium dichromate is insoluble'], '<p>Na<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> + 2KCl &rarr; K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> + 2NaCl. Sodium dichromate is very soluble, so orange crystals of the potassium salt separate on cooling. K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> is also used as a primary standard because it is not hygroscopic.</p>');
mk(2, 'chromate-dichromate equilibrium', 'The orange colour of dichromate changes to yellow on adding alkali. The reaction is', 'Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 2OH<sup>-</sup> &rarr; 2CrO<sub>4</sub><sup>2-</sup> + H<sub>2</sub>O', ['2CrO<sub>4</sub><sup>2-</sup> + 2OH<sup>-</sup> &rarr; Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O', 'Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 2OH<sup>-</sup> &rarr; 2Cr<sup>3+</sup> + O<sub>2</sub>', 'Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O &rarr; 2Cr(OH)<sub>3</sub>'], '<p>The equilibrium 2CrO<sub>4</sub><sup>2-</sup> + 2H<sup>+</sup> &rightleftharpoons; Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O shifts left in alkali (yellow chromate) and right in acid (orange dichromate). Oxidation states of Cr do not change (+6 in both).</p>', 'No redox here: Cr stays +6.');
mk(3, 'chromate-dichromate equilibrium', 'On adding a few drops of dilute H<sub>2</sub>SO<sub>4</sub> to yellow potassium chromate solution, the colour turns orange. This happens because', 'H<sup>+</sup> shifts the equilibrium towards dichromate', ['H<sup>+</sup> reduces Cr(VI) to Cr(III)', 'sulphate forms a complex with chromate', 'water is removed from the solution'], '<p>2CrO<sub>4</sub><sup>2-</sup> + 2H<sup>+</sup> &rarr; Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O. Reduction to green Cr<sup>3+</sup> needs a reducing agent, not just acid.</p>');
mk(3, 'K2Cr2O7 structure', 'The dichromate ion Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> consists of', 'two CrO<sub>4</sub> tetrahedra sharing one oxygen corner (Cr-O-Cr bond)', ['two octahedra sharing an edge', 'two square planes sharing a corner', 'a linear Cr=O=Cr chain'], '<p>Each Cr is surrounded tetrahedrally by four oxygens. The two tetrahedra share one oxygen atom (Cr-O-Cr angle about 126&deg;): six terminal and one bridging oxygen.</p>');
nat(3, 'K2Cr2O7 structure', 'How many oxygen atoms in the dichromate ion are terminal (bonded to only one Cr atom)?', 6, 0, '', '<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> has 7 oxygens: one bridging (shared by both Cr) and the other <b>6</b> terminal (three on each Cr).</p>', 'Count the bridging oxygen only once.', () => 7 - 1);
nat(4, 'K2Cr2O7 structure', 'Find the total number of Cr-O bonds (sigma and pi counted as one connection each) in Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> using the connectivity of two tetrahedra sharing one corner.', 8, 0, '', '<p>Each Cr is bonded to 4 oxygens: 3 terminal + 1 bridging. Two Cr give 2 &times; 4 = <b>8</b> Cr-O connections (the bridging oxygen is bonded to both Cr).</p>', 'The bridging O makes two Cr-O connections.', () => 2 * 4);
mk(2, 'K2Cr2O7 reactions', 'In acidic medium the dichromate ion is reduced to', 'Cr<sup>3+</sup> (green)', ['CrO<sub>4</sub><sup>2-</sup>', 'Cr(OH)<sub>3</sub>', 'CrO<sub>3</sub>'], '<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 14H<sup>+</sup> + 6e<sup>-</sup> &rarr; 2Cr<sup>3+</sup> + 7H<sub>2</sub>O, E&deg; = +1.33 V. Orange turns green as Cr(VI) is reduced.</p>');
mk(3, 'K2Cr2O7 reactions', 'How many electrons are gained per Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> ion when it is reduced to Cr<sup>3+</sup> in acid?', '6', ['3', '2', '12'], '<p>Each Cr goes from +6 to +3 (3 electrons). Two Cr atoms: 6 electrons per dichromate ion. Equivalent mass = M/6 = 294/6 = 49.</p>', 'There are two Cr atoms in each ion.');
mk(3, 'K2Cr2O7 reactions', 'The balanced equation for acidified dichromate oxidising Fe<sup>2+</sup> is', 'Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 6Fe<sup>2+</sup> + 14H<sup>+</sup> &rarr; 2Cr<sup>3+</sup> + 6Fe<sup>3+</sup> + 7H<sub>2</sub>O', ['Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 3Fe<sup>2+</sup> + 14H<sup>+</sup> &rarr; 2Cr<sup>3+</sup> + 3Fe<sup>3+</sup> + 7H<sub>2</sub>O', 'Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 5Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; 2Cr<sup>3+</sup> + 5Fe<sup>3+</sup> + 4H<sub>2</sub>O', 'Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 6Fe<sup>2+</sup> &rarr; 2Cr<sup>3+</sup> + 6Fe<sup>3+</sup> + 7O<sup>2-</sup>'], '<p>6 electrons gained per dichromate, 1 lost per Fe<sup>2+</sup>: 6 Fe<sup>2+</sup>. Charge: left -2 + 12 + 14 = 24; right 6 + 18 = 24. Oxygen: 7 goes to 7H<sub>2</sub>O using 14H<sup>+</sup>.</p>');
mk(3, 'K2Cr2O7 reactions', 'Acidified K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> oxidises iodide, and in the process', 'I<sub>2</sub> is liberated and the orange solution turns green', ['I<sub>2</sub> is consumed and the solution turns orange', 'iodate is formed and the solution remains orange', 'no change in colour occurs'], '<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 14H<sup>+</sup> + 6I<sup>-</sup> &rarr; 2Cr<sup>3+</sup> + 3I<sub>2</sub> + 7H<sub>2</sub>O. The green colour is Cr<sup>3+</sup>.</p>');
mk(3, 'K2Cr2O7 reactions', 'The chromyl chloride test for chloride ions uses', 'K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> and concentrated H<sub>2</sub>SO<sub>4</sub>, giving red CrO<sub>2</sub>Cl<sub>2</sub> vapours', ['KMnO<sub>4</sub> and dilute HCl', 'K<sub>2</sub>CrO<sub>4</sub> and dilute HNO<sub>3</sub>', 'MnO<sub>2</sub> and conc. HCl'], '<p>K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> + 4NaCl + 6H<sub>2</sub>SO<sub>4</sub> &rarr; 2KHSO<sub>4</sub> + 4NaHSO<sub>4</sub> + 2CrO<sub>2</sub>Cl<sub>2</sub>&uarr; + 3H<sub>2</sub>O. Passing the red vapours into NaOH gives yellow Na<sub>2</sub>CrO<sub>4</sub>, which with lead acetate gives a yellow precipitate of PbCrO<sub>4</sub>. The test works for ionic chlorides only (not HgCl<sub>2</sub>, a covalent chloride).</p>');
mk(4, 'K2Cr2O7 reactions', 'In the breath alcohol test the orange acidified K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> changes to green because', 'ethanol reduces Cr(VI) to Cr(III) (and is itself oxidised, finally to ethanoic acid)', ['ethanol is reduced by dichromate', 'dichromate is converted into chromate', 'Cr(VI) is oxidised to Cr(VII)'], '<p>3C<sub>2</sub>H<sub>5</sub>OH + 2Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 16H<sup>+</sup> &rarr; 3CH<sub>3</sub>COOH + 4Cr<sup>3+</sup> + 11H<sub>2</sub>O. The green Cr<sup>3+</sup> signals alcohol.</p>');
mk(4, 'K2Cr2O7 reactions', 'On adding H<sub>2</sub>O<sub>2</sub> to acidified dichromate and shaking with ether, a blue colour appears in the ether layer due to', 'CrO<sub>5</sub>, a peroxo compound with Cr in the +6 state', ['Cr<sub>2</sub>O<sub>3</sub>, with Cr in +3', 'CrO<sub>3</sub>, with Cr in +6 and a blue colour', 'Cr<sup>2+</sup> in ether'], '<p>CrO<sub>5</sub> = CrO(O<sub>2</sub>)<sub>2</sub>: one oxo (-2) and two peroxo groups (each -2 total): x - 2 - 4 = 0, so Cr is +6. The oxidation state does not change in this test, so it is not a redox reaction.</p>', 'Peroxide oxygens are -1, so CrO<sub>5</sub> is NOT Cr(+10).');
nat(4, 'oxidation state', 'The oxidation state of chromium in CrO<sub>5</sub> (which has one oxo and two peroxo groups, O<sub>2</sub><sup>2-</sup>) is', 6, 0, '', '<p>One O<sup>2-</sup> (-2) and two O<sub>2</sub><sup>2-</sup> (-4): total -6. x - 6 = 0, so x = <b>+6</b>. A naive count with five O<sup>2-</sup> gives +10, which is impossible for Cr.</p>', 'Peroxides have oxygen in the -1 state.', () => 2 + 4);
mk(3, 'chromium compounds', 'Chromium(III) hydroxide, Cr(OH)<sub>3</sub>, dissolves in both dilute acid and excess NaOH. It is', 'amphoteric, forming Cr<sup>3+</sup> and [Cr(OH)<sub>4</sub>]<sup>-</sup>', ['basic only', 'acidic only', 'neutral and insoluble in both'], '<p>Cr(OH)<sub>3</sub> + 3H<sup>+</sup> &rarr; Cr<sup>3+</sup> + 3H<sub>2</sub>O; Cr(OH)<sub>3</sub> + OH<sup>-</sup> &rarr; [Cr(OH)<sub>4</sub>]<sup>-</sup> (green solution). Both reactions show amphoteric character.</p>');
// ---------- Lanthanoids ----------
mk(1, 'lanthanoids', 'The lanthanoids are the elements with atomic numbers', '58 to 71, following lanthanum', ['89 to 103', '21 to 30', '39 to 48'], '<p>Ce (58) to Lu (71) fill the 4f subshell. Actinoids are 90 to 103.</p>');
mk(2, 'lanthanoids', 'The general electronic configuration of the lanthanoids is', '[Xe] 4f<sup>1-14</sup> 5d<sup>0-1</sup> 6s<sup>2</sup>', ['[Rn] 5f<sup>1-14</sup> 6d<sup>0-2</sup> 7s<sup>2</sup>', '[Ar] 3d<sup>1-10</sup> 4s<sup>1-2</sup>', '[Xe] 4f<sup>14</sup> 5d<sup>1-10</sup> 6s<sup>2</sup>'], '<p>The 4f subshell is being filled; 5d has 0 or 1 electron (La, Ce, Gd, Lu have one); 6s<sup>2</sup> is constant. The second option is the actinoid pattern.</p>');
mk(2, 'lanthanoid contraction', 'The lanthanoid contraction is the', 'steady decrease in the atomic and ionic radii from La to Lu', ['increase in atomic radii from La to Lu', 'decrease in the number of 4f electrons', 'decrease in oxidation states on moving from La to Lu'], '<p>Ln<sup>3+</sup> radius falls from about 106 pm (La) to 85 pm (Lu), a decrease of about 20%.</p>');
mk(2, 'lanthanoid contraction', 'The main cause of the lanthanoid contraction is', 'the poor shielding of the nuclear charge by 4f electrons', ['the increase in the number of 6s electrons', 'the repulsion between 5d electrons', 'the screening effect of 4f electrons being very high'], '<p>4f orbitals have diffuse shapes and shield the outer electrons very poorly. As the nuclear charge rises by 1 for each element, the outer electrons are pulled in, so the size shrinks steadily.</p>');
mk(3, 'lanthanoid contraction', 'Because of the lanthanoid contraction, the pair of elements with almost identical atomic radii and very similar chemistry is', 'Zr and Hf', ['Ti and Zr', 'Fe and Ru', 'Cr and Mn'], '<p>After the 4f series, Hf (5d) comes out nearly the same size as Zr (4d): about 160 and 159 pm. Their chemistry is so similar that they occur together in minerals and are hard to separate. Nb/Ta and Mo/W show the same effect.</p>');
mk(3, 'lanthanoid contraction', 'Which is NOT a consequence of the lanthanoid contraction?', 'Ce<sup>4+</sup> acts as a strong oxidising agent', ['Zr and Hf are very similar in size and properties', 'the basic strength of Ln(OH)<sub>3</sub> decreases from La to Lu', 'the third-row (5d) elements have similar radii to the second-row (4d) elements'], '<p>The strong oxidising power of Ce<sup>4+</sup> arises from its tendency to return to the stable +3 state. The other three follow from the contraction: smaller Ln<sup>3+</sup> ions polarise the OH bond more (less basic), and the 5d series is shrunk to match the 4d.</p>');
mk(3, 'lanthanoid contraction', 'Basic strength of the hydroxides Ln(OH)<sub>3</sub> decreases from La(OH)<sub>3</sub> to Lu(OH)<sub>3</sub> because', 'the ionic radius of Ln<sup>3+</sup> decreases, so the Ln-O bond becomes more covalent', ['the number of OH<sup>-</sup> changes', 'Lu is more electropositive than La', 'the oxidation state of Ln changes'], '<p>A smaller, more highly polarising Ln<sup>3+</sup> holds OH<sup>-</sup> more strongly, making the bond less ionic and the hydroxide less basic. La(OH)<sub>3</sub> is the most basic.</p>');
mk(2, 'lanthanoid oxidation states', 'The most common oxidation state of the lanthanoids is', '+3', ['+2', '+4', '+5'], '<p>All lanthanoids form Ln<sup>3+</sup> (5d<sup>1</sup>6s<sup>2</sup> electrons lost). +2 and +4 occur only where they give an empty, half-filled or filled 4f subshell.</p>');
mk(3, 'lanthanoid oxidation states', 'Ce<sup>4+</sup> and Eu<sup>2+</sup> are reasonably stable. The configurations that explain this are', '4f<sup>0</sup> for Ce<sup>4+</sup> and 4f<sup>7</sup> for Eu<sup>2+</sup>', ['4f<sup>7</sup> for Ce<sup>4+</sup> and 4f<sup>0</sup> for Eu<sup>2+</sup>', '4f<sup>14</sup> for both', '4f<sup>1</sup> for Ce<sup>4+</sup> and 4f<sup>6</sup> for Eu<sup>2+</sup>'], '<p>Ce (4f<sup>1</sup>5d<sup>1</sup>6s<sup>2</sup>) loses 4 electrons to give the noble-gas core [Xe] (4f<sup>0</sup>). Eu (4f<sup>7</sup>6s<sup>2</sup>) loses two 6s electrons to retain the half-filled 4f<sup>7</sup>. Similarly Yb<sup>2+</sup> is 4f<sup>14</sup> and Tb<sup>4+</sup> is 4f<sup>7</sup>.</p>');
mk(3, 'lanthanoid oxidation states', 'In aqueous solution Ce<sup>4+</sup> is a strong oxidising agent (E&deg; about +1.74 V) because', 'it tends to gain an electron and become the more common Ce<sup>3+</sup>', ['it has a half-filled 4f subshell', 'it has 4f<sup>14</sup>', 'Ce<sup>3+</sup> is unstable'], '<p>+3 is the characteristic lanthanoid state; Ce<sup>4+</sup> + e<sup>-</sup> &rarr; Ce<sup>3+</sup> is favourable. Eu<sup>2+</sup> likewise acts as a reducing agent as it returns to Eu<sup>3+</sup>.</p>');
mk(4, 'lanthanoid colour', 'Which of the following Ln<sup>3+</sup> ions is colourless?', 'Gd<sup>3+</sup> (4f<sup>7</sup>)', ['Pr<sup>3+</sup> (4f<sup>2</sup>)', 'Nd<sup>3+</sup> (4f<sup>3</sup>)', 'Sm<sup>3+</sup> (4f<sup>5</sup>)'], '<p>Colour arises from f-f transitions, which need a partly filled 4f subshell with room for excitation. La<sup>3+</sup> (4f<sup>0</sup>), Gd<sup>3+</sup> (4f<sup>7</sup>) and Lu<sup>3+</sup> (4f<sup>14</sup>) are colourless (also Ce<sup>3+</sup> and Yb<sup>3+</sup>, whose absorptions are in the ultraviolet). Pr<sup>3+</sup> is green, Nd<sup>3+</sup> lilac, Sm<sup>3+</sup> yellow.</p>', 'Half-filled f<sup>7</sup> is colourless in the visible region for Gd<sup>3+</sup>.');
mk(4, 'lanthanoid colour', 'Pr<sup>3+</sup> and Tm<sup>3+</sup> are both green. This is explained by the fact that', 'they have 4f<sup>2</sup> and 4f<sup>12</sup>, which have the same number of unpaired electrons (2) arranged similarly', ['both have the same atomic number', 'both have no 4f electrons', 'both are f<sup>7</sup>'], '<p>Ions with n and (14 - n) 4f electrons show similar colours (Pr/Tm, Nd/Er, Sm/Dy, Eu/Tb) because the number of unpaired electrons is the same.</p>');
mk(2, 'lanthanoid properties', 'The lanthanoids are', 'highly electropositive metals that react with water to give hydrogen', ['unreactive noble-like metals', 'non-metals', 'metals that never form oxides'], '<p>Ln metals are silvery, quite reactive, and resemble Ca. They burn in air to give oxides and react with dilute acids to liberate H<sub>2</sub> (slowly with cold water).</p>');
mk(2, 'lanthanoid uses', 'Which of the following is a use of lanthanoid compounds?', 'Misch metal in lighter flints and neodymium in strong magnets', ['Pure lanthanoids as electrical wiring', 'La metal as a fuel in nuclear reactors', 'Ln<sub>2</sub>O<sub>3</sub> as a food preservative'], '<p>Misch metal is used for lighter flints and Mg alloys; Nd-Fe-B magnets are used in motors; Eu compounds give the red phosphor in screens; Ce compounds polish glass.</p>');
// ---------- Actinoids ----------
mk(1, 'actinoids', 'The actinoids are the elements from', 'Th (90) to Lr (103), in which the 5f subshell is filled', ['Ce (58) to Lu (71)', 'Sc (21) to Zn (30)', 'Y (39) to Cd (48)'], '<p>Actinium (89) starts the series; Th to Lr fill 5f. All actinoids are radioactive.</p>');
mk(2, 'actinoids', 'The general electronic configuration of actinoids is', '[Rn] 5f<sup>1-14</sup> 6d<sup>0-2</sup> 7s<sup>2</sup>', ['[Xe] 4f<sup>1-14</sup> 5d<sup>0-1</sup> 6s<sup>2</sup>', '[Ar] 3d<sup>1-10</sup> 4s<sup>2</sup>', '[Rn] 5f<sup>0</sup> 6d<sup>1</sup> 7s<sup>2</sup> only'], '<p>5f is filled; 6d may hold 0 to 2 electrons (Th is 6d<sup>2</sup>7s<sup>2</sup>); 7s is fixed. The second option belongs to the lanthanoids.</p>');
mk(3, 'actinoid oxidation states', 'Actinoids show a greater range of oxidation states (+3 to +7) than lanthanoids because', 'the 5f, 6d and 7s orbitals have very similar energies', ['the 5f electrons are very strongly held', '5f orbitals are much lower in energy than 6d and 7s', 'actinoids are not radioactive'], '<p>The 5f orbitals extend farther from the nucleus and are close in energy to 6d and 7s, so 5f electrons can also take part in bonding. Lanthanoids have 4f well hidden in the core, so +3 dominates.</p>');
mk(4, 'actinoid properties', 'Which of the following is true for actinoids?', 'They are all radioactive, and elements beyond uranium are artificial', ['Only Th and U are radioactive', 'They are all stable and non-radioactive', 'All of them occur in large quantities in nature'], '<p>All actinoids are radioactive. Th, Pa and U occur in nature (Pu and Np in trace amounts); elements after U are made in reactors and accelerators (transuranium).</p>');
mk(4, 'actinoid properties', 'The magnetic behaviour of actinoid ions is more complex than that of lanthanoid ions because', '5f electrons are less shielded and take part in bonding and orbital effects', ['5f electrons are always paired', 'actinoid ions have no unpaired electrons', 'the 5f subshell lies deep inside the core'], '<p>5f orbitals are more spread out, and spin-orbit and bonding effects are large. Magnetic moments depend on the oxidation state and are harder to predict.</p>');
mk(4, 'actinoid properties', 'The actinoid contraction is', 'greater than the lanthanoid contraction because 5f electrons shield even more poorly than 4f electrons', ['smaller than the lanthanoid contraction', 'absent in the actinoid series', 'caused by an increase in the number of 6d electrons'], '<p>5f orbitals are more diffuse than 4f, giving even poorer shielding of the nucleus, so the steady decrease of radius from Th to Lr is larger per element.</p>');
mk(4, 'actinoid properties', 'The common oxidation state shown by all actinoids is', '+3', ['+2', '+5', '+7'], '<p>+3 is common to all actinoids; Th is +4 mostly; U shows +3 to +6 (UO<sub>2</sub><sup>2+</sup>, uranyl); Np, Pu and Am have +7 states (rare).</p>');
mk(4, 'f-block comparison', 'Compare the lanthanoids with the actinoids. Which statement is correct?', 'Actinoids show many more oxidation states and form more complexes', ['Lanthanoids form many more complexes than actinoids', 'Both series show only the +3 oxidation state', 'Actinoids have a smaller range of oxidation states'], '<p>Actinoid 5f electrons can bond, so there are many oxidation states and a rich complex chemistry. Lanthanoids mainly show +3 and form few complexes with weak bonding. Both are electropositive and reactive; all actinoids are radioactive, lanthanoids (except Pm) are not.</p>');
// ---------- Acidic and basic oxides ----------
mk(3, 'oxides', 'The oxides of manganese MnO, Mn<sub>2</sub>O<sub>3</sub>, MnO<sub>2</sub> and Mn<sub>2</sub>O<sub>7</sub> are arranged in order of increasing acidic character as', 'MnO &lt; Mn<sub>2</sub>O<sub>3</sub> &lt; MnO<sub>2</sub> &lt; Mn<sub>2</sub>O<sub>7</sub>', ['Mn<sub>2</sub>O<sub>7</sub> &lt; MnO<sub>2</sub> &lt; Mn<sub>2</sub>O<sub>3</sub> &lt; MnO', 'MnO &lt; MnO<sub>2</sub> &lt; Mn<sub>2</sub>O<sub>3</sub> &lt; Mn<sub>2</sub>O<sub>7</sub>', 'Mn<sub>2</sub>O<sub>3</sub> &lt; MnO &lt; Mn<sub>2</sub>O<sub>7</sub> &lt; MnO<sub>2</sub>'], '<p>A higher oxidation state makes a more covalent, more acidic oxide: MnO (+2) is basic, Mn<sub>2</sub>O<sub>3</sub> (+3) weakly basic, MnO<sub>2</sub> (+4) amphoteric, Mn<sub>2</sub>O<sub>7</sub> (+7) strongly acidic (gives HMnO<sub>4</sub> in water).</p>');
mk(3, 'oxides', 'Chromium forms CrO, Cr<sub>2</sub>O<sub>3</sub> and CrO<sub>3</sub>. Their nature is respectively', 'basic, amphoteric and acidic', ['acidic, amphoteric and basic', 'basic, acidic and amphoteric', 'amphoteric, basic and acidic'], '<p>CrO (Cr<sup>2+</sup>) is basic; Cr<sub>2</sub>O<sub>3</sub> (Cr<sup>3+</sup>) is amphoteric; CrO<sub>3</sub> (Cr<sup>6+</sup>) is acidic (gives chromic and dichromic acids).</p>');
// ---------- Assertion-Reason ----------
asr(2, 'transition elements', 'Zn, Cd and Hg are not regarded as transition elements.', 'Their atoms and common ions have completely filled d subshells (d<sup>10</sup>).', 0, '<p>A transition element needs an incomplete d subshell in its atoms or common ions. Zn, Cd, Hg have d<sup>10</sup> in both, so they fail the definition. R explains A.</p>');
asr(3, 'colour', 'Cu<sup>+</sup> salts are colourless but Cu<sup>2+</sup> salts are coloured.', 'Cu<sup>+</sup> has a d<sup>10</sup> configuration, while Cu<sup>2+</sup> has d<sup>9</sup> with a vacancy in the d subshell.', 0, '<p>d-d transitions need a vacancy in the d subshell. d<sup>10</sup> has none, so no visible absorption; d<sup>9</sup> has one hole in e<sub>g</sub>, so d-d absorption occurs.</p>');
asr(3, 'oxidation states', 'Transition elements show variable oxidation states.', 'The (n-1)d and ns electrons have nearly the same energy, so both can take part in bonding.', 0, '<p>Because (n-1)d and ns energies are close, different numbers of d electrons can be removed or shared in addition to the ns electrons, giving states that differ by one unit.</p>');
asr(3, 'lanthanoid oxidation states', 'Ce<sup>4+</sup> is a good oxidising agent.', 'Ce<sup>4+</sup> tends to change into the more common +3 state of lanthanoids.', 0, '<p>+3 is the stable state for lanthanoids. Ce<sup>4+</sup> + e<sup>-</sup> &rarr; Ce<sup>3+</sup> is favourable, so Ce<sup>4+</sup> oxidises other species. R explains A.</p>');
asr(3, 'KMnO4 titrations', 'Hydrochloric acid should not be used to acidify permanganate in titrations.', 'Permanganate oxidises chloride to chlorine in acid medium.', 0, '<p>2MnO<sub>4</sub><sup>-</sup> + 16H<sup>+</sup> + 10Cl<sup>-</sup> &rarr; 2Mn<sup>2+</sup> + 5Cl<sub>2</sub> + 8H<sub>2</sub>O wastes KMnO<sub>4</sub>, giving too high a titre. R is the reason for A.</p>');
asr(4, 'standard electrode potentials', 'Mn<sup>3+</sup> is a strong oxidising agent.', 'Mn<sup>3+</sup> (d<sup>4</sup>) changes to the stable half-filled d<sup>5</sup> Mn<sup>2+</sup> when it gains an electron.', 0, '<p>E&deg;(Mn<sup>3+</sup>/Mn<sup>2+</sup>) = +1.57 V is high because Mn<sup>2+</sup> has the extra-stable 3d<sup>5</sup> arrangement. R explains A.</p>');
asr(3, 'lanthanoid contraction', 'Zr and Hf have nearly the same atomic radii.', 'Zr and Hf are in the same group of the periodic table.', 1, '<p>Both are true. Elements of the same group normally get bigger down the group, so being in the same group does not explain equal size. The real cause is the lanthanoid contraction: poor shielding by the 4f electrons in between shrinks Hf to the size of Zr.</p>', 'Same group would normally mean a bigger atom lower down.');
asr(3, 'melting points', 'Zinc has a higher melting point than copper.', 'Zinc has a completely filled 3d subshell and so no unpaired d electrons for metallic bonding.', 3, '<p>A is false: Zn melts at about 420 &deg;C, while Cu melts at about 1085 &deg;C. R is true and explains why zinc is so low.</p>');
asr(3, 'KMnO4', 'The oxidation state of Mn in K<sub>2</sub>MnO<sub>4</sub> is +6, and the compound is green.', 'Mn(VI) in manganate has the d<sup>1</sup> configuration, so d-d transitions are possible.', 0, '<p>K<sub>2</sub>MnO<sub>4</sub> is green and paramagnetic with one 3d electron (d<sup>1</sup>). The colour is due to charge transfer and d-d transition. R is the typical explanation offered for the paramagnetism and colour.</p>');
asr(4, 'actinoids', 'Actinoids show a wider range of oxidation states than lanthanoids.', '5f orbitals extend further from the nucleus than 4f orbitals, and 5f, 6d and 7s are close in energy.', 0, '<p>The accessibility of 5f electrons for bonding gives oxidation states up to +7. R explains A.</p>');
asr(4, 'CrO5', 'Chromium in CrO<sub>5</sub> is in the +6 oxidation state.', 'CrO<sub>5</sub> contains two peroxide groups, in which oxygen has an oxidation number of -1.', 0, '<p>One oxo oxygen (-2) and four peroxide oxygens (-1 each): x - 2 - 4 = 0, so x = +6. R is the reason that Cr is not +10.</p>');
// ---------- Statements ----------
stm(2, 'magnetic moment', 'Fe<sup>2+</sup> has 4 unpaired electrons (free ion).', 'Fe<sup>3+</sup> has 5 unpaired electrons.', 0, '<p>Fe<sup>2+</sup> is 3d<sup>6</sup>: 4 unpaired. Fe<sup>3+</sup> is 3d<sup>5</sup>: 5 unpaired. Both correct.</p>');
stm(3, 'chromate-dichromate', 'The oxidation state of chromium is +6 in both CrO<sub>4</sub><sup>2-</sup> and Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>.', 'The conversion of chromate to dichromate in acid is a redox reaction.', 1, '<p>I is correct. II is incorrect: the change 2CrO<sub>4</sub><sup>2-</sup> + 2H<sup>+</sup> &rarr; Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O is an acid-base (condensation) reaction, and Cr stays +6.</p>');
stm(3, 'KMnO4', 'In acid, permanganate accepts 5 electrons per ion; in neutral solution it accepts 3.', 'The equivalent mass of KMnO<sub>4</sub> is M/5 in acid and M/3 in neutral medium.', 0, '<p>Mn +7 &rarr; +2 is 5 electrons; Mn +7 &rarr; +4 (MnO<sub>2</sub>) is 3. Equivalent mass = M/n-factor. Both correct.</p>');
stm(3, 'lanthanoid colour', 'La<sup>3+</sup> is colourless.', 'Lu<sup>3+</sup> is coloured.', 1, '<p>La<sup>3+</sup> (4f<sup>0</sup>) and Lu<sup>3+</sup> (4f<sup>14</sup>) are both colourless: no f-f transition is possible. II is incorrect.</p>');
stm(3, 'transition elements', 'Zinc is a transition metal because it has the configuration 3d<sup>10</sup>4s<sup>2</sup>.', 'Zn<sup>2+</sup> is colourless because it has no d-d transitions.', 2, '<p>I is incorrect: a filled d<sup>10</sup> in both atom and ion means zinc is not a transition element by the IUPAC definition. II is correct: Zn<sup>2+</sup> is d<sup>10</sup>.</p>');
stm(4, 'disproportionation', 'Cu<sup>+</sup> disproportionates in aqueous solution to Cu<sup>2+</sup> and Cu.', 'E&deg;(Cu<sup>+</sup>/Cu) = +0.52 V is greater than E&deg;(Cu<sup>2+</sup>/Cu<sup>+</sup>) = +0.15 V.', 0, '<p>2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu: E&deg;cell = 0.52 - 0.15 = +0.37 V, positive, so spontaneous. Whenever the reduction potential of the upper couple exceeds that of the lower couple, disproportionation is spontaneous. Both correct.</p>');
stm(4, 'disproportionation', 'Fe<sup>2+</sup> disproportionates in water to Fe<sup>3+</sup> and Fe.', 'E&deg;cell for 3Fe<sup>2+</sup> &rarr; 2Fe<sup>3+</sup> + Fe is -1.21 V.', 2, '<p>E&deg; = E&deg;(Fe<sup>2+</sup>/Fe) - E&deg;(Fe<sup>3+</sup>/Fe<sup>2+</sup>) = -0.44 - 0.77 = -1.21 V, negative, so Fe<sup>2+</sup> does NOT disproportionate: I is incorrect, II is correct.</p>');
stm(3, 'KMnO4 structure', 'In the manganate ion MnO<sub>4</sub><sup>2-</sup>, Mn has the d<sup>1</sup> configuration.', 'MnO<sub>4</sub><sup>2-</sup> is paramagnetic.', 0, '<p>Mn(VI) = 3d<sup>1</sup>: one unpaired electron: paramagnetic (1.73 BM). Both correct.</p>');
stm(4, 'actinoid contraction', 'The actinoid contraction is greater than the lanthanoid contraction.', '5f electrons shield the nuclear charge less effectively than 4f electrons.', 0, '<p>5f orbitals are more diffuse and shield less, so the radius falls faster across the series. Both correct.</p>');
stm(3, 'interstitial compounds', 'Interstitial compounds are hard and have high melting points.', 'Interstitial compounds have an exact stoichiometric formula.', 1, '<p>I is correct. II is incorrect: they are non-stoichiometric (TiH<sub>1.7</sub>, VH<sub>0.56</sub>).</p>');
stm(3, 'lanthanoid magnetism', 'Gd<sup>3+</sup> has 7 unpaired electrons.', 'La<sup>3+</sup> and Lu<sup>3+</sup> are diamagnetic.', 0, '<p>Gd<sup>3+</sup> is 4f<sup>7</sup> (7 unpaired); La<sup>3+</sup> 4f<sup>0</sup> and Lu<sup>3+</sup> 4f<sup>14</sup> have no unpaired electrons. Both correct.</p>');
// ---------- Multi-correct ----------
msq(3, 'magnetic properties', 'Which of the following ions are paramagnetic?', ['Fe<sup>2+</sup>', 'Zn<sup>2+</sup>', 'Cu<sup>+</sup>', 'Mn<sup>2+</sup>'], [0, 3], '<p>Fe<sup>2+</sup> (d<sup>6</sup>, 4 unpaired) and Mn<sup>2+</sup> (d<sup>5</sup>, 5 unpaired). Zn<sup>2+</sup> and Cu<sup>+</sup> are d<sup>10</sup>.</p>');
msq(3, 'colour', 'Which of the following aqueous ions are colourless?', ['Sc<sup>3+</sup>', 'Zn<sup>2+</sup>', 'Ti<sup>4+</sup>', 'Cr<sup>3+</sup>'], [0, 1, 2], '<p>Sc<sup>3+</sup> (d<sup>0</sup>), Zn<sup>2+</sup> (d<sup>10</sup>) and Ti<sup>4+</sup> (d<sup>0</sup>) are colourless. Cr<sup>3+</sup> (d<sup>3</sup>) is violet.</p>');
msq(3, 'oxidation states', 'Which of these elements can show a +7 oxidation state?', ['Mn', 'Cr', 'Fe', 'Re'], [0, 3], '<p>Mn in MnO<sub>4</sub><sup>-</sup> and Re in ReO<sub>4</sub><sup>-</sup>. Cr reaches +6 and Fe +6 (ferrate).</p>');
msq(4, 'K2Cr2O7', 'Which statements are correct for acidified K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>?', ['It oxidises iodide to iodine', 'Cr is in the +6 state', 'The ion is paramagnetic', 'The ion has two CrO<sub>4</sub> tetrahedra sharing a corner'], [0, 1, 3], '<p>Cr(VI) is d<sup>0</sup>, so the dichromate ion is diamagnetic (third statement false). The other three are correct.</p>');
msq(4, 'KMnO4', 'Which of the following are correct for potassium permanganate?', ['It evolves oxygen on heating', 'In acid it is reduced to Mn<sup>2+</sup>', 'The permanganate ion has an unpaired electron', 'The permanganate ion is tetrahedral'], [0, 1, 3], '<p>MnO<sub>4</sub><sup>-</sup> is d<sup>0</sup> and diamagnetic. The ion is tetrahedral; KMnO<sub>4</sub> on heating gives K<sub>2</sub>MnO<sub>4</sub>, MnO<sub>2</sub> and O<sub>2</sub>; in acid it goes to Mn<sup>2+</sup>.</p>');
msq(4, 'lanthanoid contraction', 'Which of the following are consequences of the lanthanoid contraction?', ['Zr and Hf have nearly identical radii', 'The basic character of Ln(OH)<sub>3</sub> decreases from La to Lu', 'It is difficult to separate the lanthanoids from each other', 'The atomic radii of Ln increase from La to Lu'], [0, 1, 2], '<p>Similar radii of 4d and 5d elements, decreasing basicity and the very similar chemistry (hence difficult separation) are consequences. Radii decrease, not increase, from La to Lu.</p>');
msq(4, 'interstitial compounds', 'Properties of interstitial compounds include', ['high melting points', 'hardness', 'electrical conductivity', 'ionic bonding between metal and the small atom'], [0, 1, 2], '<p>Interstitial compounds keep metallic conduction and are very hard with high melting points. The small atoms (H, C, N) are trapped in voids rather than forming ionic bonds.</p>');
msq(5, 'disproportionation', 'Which of the following disproportionate in aqueous solution (standard conditions)?', ['Cu<sup>+</sup>', 'MnO<sub>4</sub><sup>2-</sup> in acid', 'Au<sup>+</sup>', 'Fe<sup>2+</sup>'], [0, 1, 2], '<p>Cu<sup>+</sup>: E&deg; = 0.52 - 0.15 = +0.37 V. Manganate in acid: 3MnO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> &rarr; 2MnO<sub>4</sub><sup>-</sup> + MnO<sub>2</sub> + 2H<sub>2</sub>O. Au<sup>+</sup>: E&deg; = 1.69 - 1.40 = +0.29 V. Fe<sup>2+</sup>: E&deg; = -1.21 V, so it is stable.</p>');
msq(5, 'd<sup>5</sup> ions', 'Which of the following species have a d<sup>5</sup> configuration?', ['Mn<sup>2+</sup>', 'Fe<sup>3+</sup>', 'Cr<sup>+</sup>', 'Co<sup>2+</sup>'], [0, 1, 2], '<p>Mn<sup>2+</sup>: 3d<sup>5</sup>. Fe<sup>3+</sup>: 3d<sup>5</sup>. Cr<sup>+</sup>: from 3d<sup>5</sup>4s<sup>1</sup> lose 4s to give 3d<sup>5</sup>. Co<sup>2+</sup>: 3d<sup>7</sup>.</p>');
msq(4, 'lanthanoid oxidation states', 'Which of the following ions are known with the stable configurations indicated?', ['Ce<sup>4+</sup> (4f<sup>0</sup>)', 'Eu<sup>2+</sup> (4f<sup>7</sup>)', 'Yb<sup>2+</sup> (4f<sup>14</sup>)', 'La<sup>4+</sup> (4f<sup>-1</sup>)'], [0, 1, 2], '<p>La has only 4f<sup>0</sup>5d<sup>1</sup>6s<sup>2</sup>: La<sup>4+</sup> would need to remove a core electron, which is not possible.</p>');
// ---------- Match ----------
mat(2, 'colour of ions', 'm2', 'Match each aqueous ion (List I) with its colour (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], '<p>Cu<sup>2+</sup> is blue (p), Mn<sup>2+</sup> pale pink (q), Ni<sup>2+</sup> green (r), Fe<sup>3+</sup> yellow-brown (s).</p>');
mat(3, 'manganese compounds', 'm3', 'Match each manganese compound (List I) with the oxidation state of Mn (List II).', 'A-s, B-r, C-q, D-p', ['A-p, B-q, C-r, D-s', 'A-s, B-q, C-r, D-p', 'A-r, B-s, C-p, D-q'], '<p>KMnO<sub>4</sub>: +7 (s). K<sub>2</sub>MnO<sub>4</sub>: +6 (r). MnO<sub>2</sub>: +4 (q). MnSO<sub>4</sub>: +2 (p).</p>');
mat(3, 'f-block configurations', 'm4', 'Match each ion (List I) with its 4f configuration (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-r, B-q, C-p, D-s'], '<p>Ce<sup>4+</sup>: 4f<sup>0</sup>. Eu<sup>2+</sup>: 4f<sup>7</sup>. Yb<sup>2+</sup>: 4f<sup>14</sup>. Sm<sup>2+</sup> (Sm is 4f<sup>6</sup>6s<sup>2</sup>): 4f<sup>6</sup>.</p>');
mat(2, 'minerals', 'm5', 'Match each mineral (List I) with its composition (List II).', 'A-p, B-q, C-r, D-s', ['A-q, B-p, C-r, D-s', 'A-p, B-q, C-s, D-r', 'A-s, B-q, C-r, D-p'], '<p>Pyrolusite is MnO<sub>2</sub>; chromite is FeCr<sub>2</sub>O<sub>4</sub>; haematite is Fe<sub>2</sub>O<sub>3</sub>; monazite is a lanthanoid (and thorium) phosphate, the chief source of lanthanoids.</p>');
// ---------- Passages ----------
PN(3, 'KMnO4 titration', 'p1', 'Find the molarity of the Fe<sup>2+</sup> solution in mol/L.', 0.125, 0.001, 'M', '<p>n(MnO<sub>4</sub><sup>-</sup>) = 0.0200 &times; 25.0 mL = 0.500 mmol. Each MnO<sub>4</sub><sup>-</sup> oxidises 5 Fe<sup>2+</sup>: 2.50 mmol Fe<sup>2+</sup>.</p><p>Molarity = 2.50 mmol/20.0 mL = <b>0.125 M</b>.</p>', 'Five Fe<sup>2+</sup> per permanganate.', () => 0.02 * 25 * 5 / 20);
P(3, 'KMnO4 titration', 'p1', 'The end point of this titration is seen when', 'one extra drop of KMnO<sub>4</sub> gives a permanent pale pink colour', ['the solution turns green', 'a brown precipitate forms', 'the solution turns blue-black'], '<p>Permanganate is its own indicator: it is decolourised while Fe<sup>2+</sup> is present; the first excess drop colours the solution pale pink.</p>');
P(4, 'KMnO4 titration', 'p1', 'If the Fe<sup>2+</sup> solution had been acidified with HCl instead of H<sub>2</sub>SO<sub>4</sub>, the titre would be', 'higher than the true value, because Cl<sup>-</sup> also consumes MnO<sub>4</sub><sup>-</sup>', ['lower than the true value', 'unchanged', 'impossible to read'], '<p>Some permanganate oxidises Cl<sup>-</sup> to Cl<sub>2</sub>, so more KMnO<sub>4</sub> is needed to reach the end point, and the calculated Fe<sup>2+</sup> would be too high.</p>');
PN(3, 'K2Cr2O7 solution', 'p2', 'Find the molarity of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (M = 294) in the solution.', 0.01, 0.0002, 'M', '<p>n = 0.294/294 = 1.00 &times; 10<sup>-3</sup> mol in 0.100 L: C = <b>0.0100 M</b>.</p>', '', () => 0.294 / 294 / 0.1);
PN(3, 'K2Cr2O7 solution', 'p2', 'Find its normality as an oxidising agent in acid medium (n-factor 6).', 0.06, 0.001, 'N', '<p>Normality = molarity &times; n-factor = 0.0100 &times; 6 = <b>0.060 N</b>.</p>', 'The n-factor is 6 (two Cr atoms, 3 electrons each).', () => 0.01 * 6);
PN(4, 'K2Cr2O7 solution', 'p2', 'What volume (in mL) of this solution is needed to oxidise 10.0 mL of 0.100 M FeSO<sub>4</sub> in acid?', 16.7, 0.2, 'mL', '<p>n(Fe<sup>2+</sup>) = 1.00 mmol. 6Fe<sup>2+</sup> per Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>: 1.00/6 = 0.1667 mmol.</p><p>V = 0.1667 mmol/0.0100 M = <b>16.7 mL</b>.</p>', '', () => 1 / 6 / 0.01);
PN(3, 'lanthanoid contraction', 'p3', 'Find the percentage decrease in the ionic radius from La<sup>3+</sup> to Lu<sup>3+</sup> (to one decimal place).', 19.8, 0.2, '%', '<p>(106 - 85)/106 &times; 100 = 21/106 &times; 100 = <b>19.8%</b>.</p>', '', () => (106 - 85) / 106 * 100);
PN(3, 'lanthanoid contraction', 'p3', 'Find the average decrease in ionic radius per element (pm) between La and Lu. (There are 14 steps from La to Lu.)', 1.5, 0.05, 'pm', '<p>Total decrease 21 pm over 14 steps: 21/14 = <b>1.5 pm</b> per element.</p>', 'Count the steps, not the elements (La to Lu is 14 steps, 15 elements).', () => 21 / 14);
P(3, 'lanthanoid contraction', 'p3', 'Which hydroxide is the weakest base?', 'Lu(OH)<sub>3</sub>', ['La(OH)<sub>3</sub>', 'Gd(OH)<sub>3</sub>', 'Ce(OH)<sub>3</sub>'], '<p>The smallest ion Lu<sup>3+</sup> polarises the O-H bond most, so Lu(OH)<sub>3</sub> is the least basic; La(OH)<sub>3</sub> is the most basic.</p>');
// ---------- Numerical, mixed, and top-rank items ----------
nat(3, 'KMnO4 preparation', 'Calculate the mass (in g) of KMnO<sub>4</sub> (M = 158) that can be obtained from 8.7 g of MnO<sub>2</sub> (M = 87) if every Mn atom is converted to permanganate (MnO<sub>2</sub> &rarr; K<sub>2</sub>MnO<sub>4</sub> &rarr; KMnO<sub>4</sub>, 100% yield).', 15.8, 0.1, 'g', '<p>n(MnO<sub>2</sub>) = 8.7/87 = 0.10 mol. One Mn atom gives one MnO<sub>4</sub><sup>-</sup> (electrolytic oxidation of manganate), so n(KMnO<sub>4</sub>) = 0.10 mol.</p><p>Mass = 0.10 &times; 158 = <b>15.8 g</b>.</p>', '', () => 0.1 * 158);
nat(4, 'KMnO4 preparation', 'When K<sub>2</sub>MnO<sub>4</sub> (0.30 mol) disproportionates completely in acid (3MnO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> &rarr; 2MnO<sub>4</sub><sup>-</sup> + MnO<sub>2</sub> + 2H<sub>2</sub>O), how many grams of KMnO<sub>4</sub> are formed? (M = 158)', 31.6, 0.2, 'g', '<p>3 mol manganate give 2 mol permanganate, so 0.30 mol gives 0.20 mol. Mass = 0.20 &times; 158 = <b>31.6 g</b>. Only two thirds of the Mn is recovered as KMnO<sub>4</sub>; the rest is MnO<sub>2</sub>.</p>', 'The electrolytic route has no loss of Mn; the disproportionation route loses one third as MnO<sub>2</sub>.', () => 0.3 * 2 / 3 * 158);
nat(4, 'KMnO4 and Faraday', 'K<sub>2</sub>MnO<sub>4</sub> is oxidised to KMnO<sub>4</sub> by electrolysis. How many grams of KMnO<sub>4</sub> (M = 158) form when 5.00 A flows for 1930 s? (F = 96500 C/mol, 100% current efficiency.)', 15.8, 0.2, 'g', '<p>Q = 5.00 &times; 1930 = 9650 C = 0.100 mol e<sup>-</sup>. MnO<sub>4</sub><sup>2-</sup> &rarr; MnO<sub>4</sub><sup>-</sup> + e<sup>-</sup> uses 1 electron per ion, so 0.100 mol KMnO<sub>4</sub>.</p><p>Mass = 0.100 &times; 158 = <b>15.8 g</b>.</p>', 'One electron per ion, not five.', () => 5 * 1930 / 96500 * 158);
nat(3, 'stoichiometry of KMnO4', 'How many grams of oxalic acid, H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> (M = 90), are oxidised in acid by 0.316 g of KMnO<sub>4</sub> (M = 158)?', 0.45, 0.005, 'g', '<p>n(KMnO<sub>4</sub>) = 0.316/158 = 2.00 &times; 10<sup>-3</sup> mol. 2MnO<sub>4</sub><sup>-</sup> : 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup>, so n(oxalic) = 2.00 &times; 10<sup>-3</sup> &times; 5/2 = 5.00 &times; 10<sup>-3</sup> mol.</p><p>Mass = 5.00 &times; 10<sup>-3</sup> &times; 90 = <b>0.45 g</b>.</p>', '', () => 0.316 / 158 * 2.5 * 90);
nat(4, 'redox stoichiometry', 'How many moles of KMnO<sub>4</sub> are needed in acid to oxidise one mole of ferrous oxalate, FeC<sub>2</sub>O<sub>4</sub>? (Fe<sup>2+</sup> &rarr; Fe<sup>3+</sup> and C<sub>2</sub>O<sub>4</sub><sup>2-</sup> &rarr; 2CO<sub>2</sub>.)', 0.6, 0.01, 'mol', '<p>Electrons lost per FeC<sub>2</sub>O<sub>4</sub>: Fe 1 + oxalate 2 = 3. Each MnO<sub>4</sub><sup>-</sup> gains 5.</p><p>Moles of KMnO<sub>4</sub> = 3/5 = <b>0.6</b>.</p>', 'Both Fe<sup>2+</sup> and oxalate are oxidised.', () => 3 / 5);
nat(4, 'redox stoichiometry', 'In acid solution, how many moles of FeC<sub>2</sub>O<sub>4</sub> are oxidised by one mole of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>?', 2, 0, '', '<p>Dichromate takes 6 electrons. Each FeC<sub>2</sub>O<sub>4</sub> gives 3 (1 from Fe<sup>2+</sup> and 2 from oxalate). Moles = 6/3 = <b>2</b>.</p>', 'Do not count only the iron.', () => 6 / 3);
nat(5, 'KMnO4 and sulphite', '25.0 mL of 0.100 M Na<sub>2</sub>SO<sub>3</sub> is oxidised to sulphate by 20.0 mL of KMnO<sub>4</sub> solution in neutral medium (MnO<sub>4</sub><sup>-</sup> &rarr; MnO<sub>2</sub>). Find the molarity of the KMnO<sub>4</sub> in units of 10<sup>-2</sup> M.', 8.33, 0.05, '&times; 10<sup>-2</sup> M', '<p>Sulphite &rarr; sulphate: 2 electrons per SO<sub>3</sub><sup>2-</sup>; electrons supplied = 2.50 mmol &times; 2 = 5.00 mmol.</p><p>Neutral MnO<sub>4</sub><sup>-</sup> &rarr; MnO<sub>2</sub>: 3 electrons per ion, so n(MnO<sub>4</sub><sup>-</sup>) = 5.00/3 = 1.667 mmol in 20.0 mL: M = 0.0833 = <b>8.33 &times; 10<sup>-2</sup> M</b>.</p>', 'Neutral medium: n-factor 3, not 5.', () => 2.5 * 2 / 3 / 20 / 1e-2);
nat(4, 'disproportionation', 'E&deg;(Cu<sup>+</sup>/Cu) = +0.52 V and E&deg;(Cu<sup>2+</sup>/Cu<sup>+</sup>) = +0.15 V. Find E&deg;cell (in V) for 2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu.', 0.37, 0.01, 'V', '<p>Cathode (reduction): Cu<sup>+</sup> + e<sup>-</sup> &rarr; Cu, 0.52 V. Anode (oxidation): Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + e<sup>-</sup>, 0.15 V.</p><p>E&deg;cell = 0.52 - 0.15 = <b>+0.37 V</b>, so Cu<sup>+</sup> disproportionates.</p>', '', () => 0.52 - 0.15);
nat(4, 'disproportionation', 'Find &Delta;G&deg; (in kJ) at 298 K for the disproportionation 2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu with E&deg;cell = 0.37 V. (n = 1, F = 96500 C/mol)', -35.7, 0.2, 'kJ', '<p>&Delta;G&deg; = -nFE&deg; = -1 &times; 96500 &times; 0.37 = -35705 J = <b>-35.7 kJ</b>.</p>', 'Here n = 1 for the reaction as written.', () => -96500 * 0.37 / 1000);
nat(4, 'Nernst equation', 'Find the reduction potential at pH 1 of MnO<sub>4</sub><sup>-</sup> + 8H<sup>+</sup> + 5e<sup>-</sup> &rarr; Mn<sup>2+</sup> + 4H<sub>2</sub>O when [MnO<sub>4</sub><sup>-</sup>] = [Mn<sup>2+</sup>] = 1 M. E&deg; = 1.51 V; use 0.059 V.', 1.42, 0.01, 'V', '<p>E = 1.51 - (0.059/5) log(1/[H<sup>+</sup>]<sup>8</sup>) = 1.51 - 0.0118 &times; 8 = 1.51 - 0.0944 = <b>1.416 V</b>.</p>', 'The H<sup>+</sup> term is raised to the eighth power.', () => 1.51 - 0.059 / 5 * 8);
nat(4, 'standard electrode potential', 'Find E&deg;cell for Zn | Zn<sup>2+</sup> || Fe<sup>3+</sup>, Fe<sup>2+</sup> | Pt. E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V, E&deg;(Fe<sup>3+</sup>/Fe<sup>2+</sup>) = +0.77 V.', 1.53, 0.01, 'V', '<p>Cathode: Fe<sup>3+</sup>/Fe<sup>2+</sup> (+0.77 V). Anode: Zn (-0.76 V). E&deg;cell = 0.77 - (-0.76) = <b>1.53 V</b>.</p>', '', () => 0.77 + 0.76);
mk(4, 'standard electrode potentials', 'Which of the following 3d metals does NOT liberate hydrogen from dilute acids? (E&deg;: Zn -0.76, Fe -0.44, Ni -0.25, Cu +0.34 V)', 'Cu', ['Zn', 'Fe', 'Ni'], '<p>A metal liberates H<sub>2</sub> from acid only if E&deg;(M<sup>2+</sup>/M) &lt; 0. Copper has a positive E&deg; (+0.34 V), so it does not. (Cu does dissolve in nitric acid, but that is by NO<sub>3</sub><sup>-</sup> reduction, not hydrogen evolution.)</p>', 'Cu reacts with HNO<sub>3</sub> but gives NO or NO<sub>2</sub>, not H<sub>2</sub>.');
mk(4, 'mixed', 'In which of the following is the spin-only magnetic moment the LARGEST? (all high spin octahedral aqua ions)', '[Mn(H<sub>2</sub>O)<sub>6</sub>]<sup>2+</sup>', ['[Fe(H<sub>2</sub>O)<sub>6</sub>]<sup>2+</sup>', '[Cr(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup>', '[Ni(H<sub>2</sub>O)<sub>6</sub>]<sup>2+</sup>'], '<p>Mn<sup>2+</sup> d<sup>5</sup>: 5 unpaired, 5.92 BM. Fe<sup>2+</sup> d<sup>6</sup>: 4 (4.90). Cr<sup>3+</sup> d<sup>3</sup>: 3 (3.87). Ni<sup>2+</sup> d<sup>8</sup>: 2 (2.83).</p>');
mk(5, 'mixed', 'The ion MnO<sub>4</sub><sup>-</sup> (E&deg; = +1.51 V in acid) is a stronger oxidising agent in acid than Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> (+1.33 V). Which statement follows?', 'MnO<sub>4</sub><sup>-</sup> oxidises Cl<sup>-</sup> (E&deg;(Cl<sub>2</sub>/Cl<sup>-</sup>) = 1.36 V) but Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> does not under standard conditions', ['Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> oxidises Cl<sup>-</sup> and MnO<sub>4</sub><sup>-</sup> does not', 'both oxidise Cl<sup>-</sup> equally easily', 'neither can oxidise Cl<sup>-</sup>'], '<p>For a spontaneous reaction E&deg;cell &gt; 0. MnO<sub>4</sub><sup>-</sup> with Cl<sup>-</sup>: 1.51 - 1.36 = +0.15 V (feasible). Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>: 1.33 - 1.36 = -0.03 V (not feasible at standard conditions). This is why dichromate can be used in HCl in titrations but permanganate cannot.</p>', 'The margin is small for dichromate; real concentrations and heat can change this.');
mk(5, 'mixed', 'In [Ti(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup> the single d electron absorbs about 500 nm light. This shows that', 'the t<sub>2g</sub>-e<sub>g</sub> splitting is about 20000 cm<sup>-1</sup> (about 240 kJ/mol), and the ion is coloured because it is d<sup>1</sup>', ['the ion is d<sup>0</sup> and colourless', 'the splitting is zero', 'the ion has no unpaired electron'], '<p>Wavenumber = 10<sup>7</sup>/500 nm = 20000 cm<sup>-1</sup>, which is about 239 kJ/mol. Ti<sup>3+</sup> is 3d<sup>1</sup>, so it has an electron that can be promoted and the ion is coloured (purple).</p>');
// ---------- More warm-ups and top-rank items ----------
mk(1, 'd-block', 'Iron, copper and zinc all belong to the', 'd-block', ['s-block', 'p-block', 'f-block'], '<p>Elements whose last electron enters a d subshell form the d-block (groups 3 to 12). Zn is in the d-block but is not a transition element.</p>');
mk(1, 'colour', 'The colour of an aqueous solution of potassium permanganate is', 'purple', ['orange', 'green', 'colourless'], '<p>MnO<sub>4</sub><sup>-</sup> is intensely purple. Dichromate is orange, manganate is green, and Mn<sup>2+</sup> is almost colourless.</p>');
mk(1, 'colour', 'Aqueous potassium dichromate in acid is', 'orange', ['yellow', 'purple', 'blue'], '<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> is orange. Chromate CrO<sub>4</sub><sup>2-</sup> (alkaline) is yellow.</p>');
mk(1, 'lanthanoids', 'Which of these is a lanthanoid?', 'cerium (Ce)', ['uranium (U)', 'iron (Fe)', 'copper (Cu)'], '<p>Ce (Z = 58) is a lanthanoid. U is an actinoid; Fe and Cu are d-block elements.</p>');
mk(1, 'actinoids', 'Which of these is an actinoid?', 'uranium (U)', ['cerium (Ce)', 'lanthanum (La)', 'lutetium (Lu)'], '<p>U (Z = 92) fills the 5f subshell and is an actinoid. Ce and Lu are lanthanoids; La is the element that heads the lanthanoid series.</p>');
mk(1, 'physical properties', 'Which d-block metal is a liquid at room temperature?', 'mercury', ['zinc', 'cadmium', 'copper'], '<p>Mercury (melting point -39 &deg;C) is liquid, because its filled d<sup>10</sup>s<sup>2</sup> shell gives very weak metallic bonding.</p>');
mk(1, 'catalytic property', 'The catalyst used in the manufacture of ammonia by the Haber process is', 'finely divided iron', ['platinum gauze', 'V<sub>2</sub>O<sub>5</sub>', 'nickel'], '<p>Haber: N<sub>2</sub> + 3H<sub>2</sub> &rarr; 2NH<sub>3</sub> over iron (with promoters such as Mo or K<sub>2</sub>O).</p>');
mk(1, 'transition elements', 'Which one of these is NOT a member of the 3d series?', 'Ca', ['V', 'Fe', 'Ni'], '<p>The 3d series runs from Sc (21) to Zn (30). Ca (Z = 20) is an s-block element.</p>');
mk(1, 'magnetic properties', 'The unit commonly used for magnetic moment is', 'Bohr magneton (BM)', ['tesla', 'ohm', 'coulomb'], '<p>The Bohr magneton is the natural unit for the magnetic moment of electrons (1 BM = 9.27 &times; 10<sup>-24</sup> J/T). Tesla measures field strength.</p>');
nat(1, 'oxidation states', 'What is the highest oxidation state of manganese?', 7, 0, '', '<p>Mn has 3d<sup>5</sup>4s<sup>2</sup>: 7 valence electrons, so the highest state is <b>+7</b> (KMnO<sub>4</sub>, Mn<sub>2</sub>O<sub>7</sub>).</p>', '', () => 5 + 2);
nat(1, 'magnetic properties', 'How many unpaired electrons does Zn<sup>2+</sup> have?', 0, 0, '', '<p>Zn<sup>2+</sup> is 3d<sup>10</sup>: all electrons are paired, so <b>0</b>.</p>', '', () => 0);
nat(1, 'electronic configuration', 'How many 3d electrons are present in a ground-state Cr atom?', 5, 0, '', '<p>Cr is 3d<sup>5</sup>4s<sup>1</sup>: <b>5</b> electrons in 3d.</p>', '', () => 5);
// L4
nat(4, 'K2Cr2O7 analysis', 'In iodometry, 20.0 mL of 0.100 M K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> is treated with excess KI in acid. The liberated iodine is titrated with 0.100 M sodium thiosulphate (I<sub>2</sub> + 2S<sub>2</sub>O<sub>3</sub><sup>2-</sup> &rarr; 2I<sup>-</sup> + S<sub>4</sub>O<sub>6</sub><sup>2-</sup>). What volume (in mL) of thiosulphate is needed?', 120, 1, 'mL', '<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 14H<sup>+</sup> + 6I<sup>-</sup> &rarr; 2Cr<sup>3+</sup> + 3I<sub>2</sub> + 7H<sub>2</sub>O. n(dichromate) = 0.100 &times; 20.0 = 2.00 mmol, giving 6.00 mmol I<sub>2</sub>.</p><p>Each I<sub>2</sub> needs 2 thiosulphate: 12.0 mmol. V = 12.0/0.100 = <b>120 mL</b>. (In short: 1 Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> &equiv; 3 I<sub>2</sub> &equiv; 6 S<sub>2</sub>O<sub>3</sub><sup>2-</sup>.)</p>', 'Two thiosulphate per iodine molecule.', () => 20 * 0.1 * 6 / 0.1);
nat(4, 'preparing a standard solution', 'How many grams of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (M = 294) are needed to prepare 250 mL of 0.100 N solution (acid medium, n-factor 6)?', 1.225, 0.01, 'g', '<p>Equivalent mass = 294/6 = 49. Mass = N &times; equivalent mass &times; V(L) = 0.100 &times; 49 &times; 0.250 = <b>1.225 g</b>.</p>', 'Use the equivalent mass, not the molar mass.', () => 0.1 * 49 * 0.25);
nat(4, 'breath analyser', 'In acid, K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> oxidises ethanol to ethanoic acid (CH<sub>3</sub>CH<sub>2</sub>OH &rarr; CH<sub>3</sub>COOH, 4 electrons per molecule). How many moles of ethanol are oxidised by 1 mol of K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub>?', 1.5, 0.01, 'mol', '<p>Dichromate takes 6 electrons. Each ethanol gives 4. Moles ethanol = 6/4 = <b>1.5</b>. (Equation: 3C<sub>2</sub>H<sub>5</sub>OH + 2Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 16H<sup>+</sup> &rarr; 3CH<sub>3</sub>COOH + 4Cr<sup>3+</sup> + 11H<sub>2</sub>O.)</p>', '', () => 6 / 4);
mk(4, 'standard electrode potentials', 'E&deg;(Co<sup>3+</sup>/Co<sup>2+</sup>) = +1.97 V is very high, so', 'Co<sup>3+</sup> can oxidise water, and simple Co(III) salts are unstable in water', ['Co<sup>3+</sup> is a strong reducing agent', 'Co<sup>2+</sup> is oxidised by water', 'Co<sup>3+</sup> is stabilised by the d<sup>7</sup> configuration'], '<p>E&deg;(O<sub>2</sub>/H<sub>2</sub>O) is about +1.23 V, so Co<sup>3+</sup> (+1.97 V) oxidises water to O<sub>2</sub>. Co(III) is stable only in complexes (e.g. [Co(NH<sub>3</sub>)<sub>6</sub>]<sup>3+</sup>), where the ligands stabilise it.</p>');
mk(4, 'copper chemistry', 'When KI solution is added to CuSO<sub>4</sub> solution, a white precipitate with brown colour of iodine forms. The balanced reaction and role of iodide are', '2Cu<sup>2+</sup> + 4I<sup>-</sup> &rarr; Cu<sub>2</sub>I<sub>2</sub> + I<sub>2</sub>; I<sup>-</sup> reduces Cu(II) to Cu(I) which is stabilised as insoluble CuI', ['Cu<sup>2+</sup> + 2I<sup>-</sup> &rarr; CuI<sub>2</sub>, a soluble blue complex', 'Cu<sup>2+</sup> + I<sup>-</sup> &rarr; Cu + I<sub>2</sub>', '2Cu<sup>2+</sup> + 2I<sup>-</sup> &rarr; 2Cu<sup>3+</sup> + I<sub>2</sub>'], '<p>Cu<sup>2+</sup> is a mild oxidant but oxidises I<sup>-</sup> because insoluble CuI removes Cu<sup>+</sup> from solution, making the potential for Cu<sup>2+</sup>/CuI much higher than 0.15 V. CuI is white and I<sub>2</sub> turns the solution brown. CuI<sub>2</sub> does not exist.</p>');
// L5
nat(5, 'disproportionation', 'E&deg;(MnO<sub>4</sub><sup>2-</sup>/MnO<sub>2</sub>) = +2.26 V and E&deg;(MnO<sub>4</sub><sup>-</sup>/MnO<sub>4</sub><sup>2-</sup>) = +0.56 V. Find E&deg;cell (V) for the disproportionation 3MnO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> &rarr; 2MnO<sub>4</sub><sup>-</sup> + MnO<sub>2</sub> + 2H<sub>2</sub>O.', 1.7, 0.01, 'V', '<p>Manganate is reduced to MnO<sub>2</sub> (cathode, 2.26 V) and oxidised to permanganate (anode, 0.56 V).</p><p>E&deg;cell = 2.26 - 0.56 = <b>+1.70 V</b>: very spontaneous in acid.</p>', '', () => 2.26 - 0.56);
nat(5, 'chromate-dichromate equilibrium', 'For 2CrO<sub>4</sub><sup>2-</sup> + 2H<sup>+</sup> &rightleftharpoons; Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + H<sub>2</sub>O, K = [Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>]/([CrO<sub>4</sub><sup>2-</sup>]<sup>2</sup>[H<sup>+</sup>]<sup>2</sup>) = 4.0 &times; 10<sup>14</sup>. At what pH are [Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>] and [CrO<sub>4</sub><sup>2-</sup>] both equal to 0.10 M?', 6.8, 0.03, '', '<p>[H<sup>+</sup>]<sup>2</sup> = [Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>]/(K[CrO<sub>4</sub><sup>2-</sup>]<sup>2</sup>) = 0.10/(4.0 &times; 10<sup>14</sup> &times; 0.010) = 2.5 &times; 10<sup>-14</sup>.</p><p>[H<sup>+</sup>] = 1.58 &times; 10<sup>-7</sup> M, so pH = <b>6.80</b>. Below this pH dichromate dominates (orange), above it chromate (yellow).</p>', 'The H<sup>+</sup> term is squared.', () => -l10(Math.sqrt(0.1 / (4e14 * 0.01))));
nat(5, 'mixed counting', 'Find the total number of unpaired electrons in a Cr atom, a Cu atom, an Fe<sup>3+</sup> ion and a Zn<sup>2+</sup> ion (ground states, free species).', 12, 0, '', '<p>Cr 3d<sup>5</sup>4s<sup>1</sup>: 6. Cu 3d<sup>10</sup>4s<sup>1</sup>: 1. Fe<sup>3+</sup> 3d<sup>5</sup>: 5. Zn<sup>2+</sup> 3d<sup>10</sup>: 0. Total = 6 + 1 + 5 + 0 = <b>12</b>.</p>', 'Cr and Cu atoms are exceptions to the 4s<sup>2</sup> rule.', () => 6 + 1 + 5 + 0);
nat(5, 'mixed counting', 'The spin-only magnetic moments of two ions are in the ratio sqrt(35) : sqrt(15). The first is high-spin octahedral Mn<sup>2+</sup>. If the second ion has the 3d<sup>n</sup> configuration with the stated moment, what is the number of d electrons n? (Take the ion as a free ion with n &lt; 5.)', 3, 0, '', '<p>Mn<sup>2+</sup>: 5 unpaired, &mu;<sup>2</sup> = 5 &times; 7 = 35. So the second ion has &mu;<sup>2</sup> = 15 = n(n+2) with n = 3 unpaired, which for n &lt; 5 means 3d<sup>3</sup> (such as Cr<sup>3+</sup> or V<sup>2+</sup>).</p><p>Answer: <b>3</b>.</p>', '', () => 3);
mk(5, 'lanthanoid contraction', 'Silver and gold have almost identical atomic radii (about 144 pm) although gold lies a full period below silver. The main reason is', 'the lanthanoid contraction (poor shielding by 4f electrons)', ['silver has two extra shells', 'gold has fewer electrons than silver', 'the d<sup>10</sup> configuration of silver is larger'], '<p>Between Ag (4d) and Au (5d) the 4f subshell is filled. 4f electrons shield poorly, so the 5d metals are much smaller than expected. (Relativistic contraction of 6s adds to the effect, but the textbook cause is the lanthanoid contraction.) This also makes Au very dense and unreactive.</p>', 'The usual periodic trend (bigger down the group) fails after the lanthanoids.');
mk(5, 'oxidation states', 'Which of the following correctly lists the oxidation states of Mn in MnO<sub>4</sub><sup>-</sup>, MnO<sub>4</sub><sup>2-</sup>, MnO<sub>2</sub> and Mn<sub>2</sub>O<sub>3</sub> and the number of d electrons in each?', '+7 (d<sup>0</sup>), +6 (d<sup>1</sup>), +4 (d<sup>3</sup>), +3 (d<sup>4</sup>)', ['+7 (d<sup>0</sup>), +6 (d<sup>1</sup>), +4 (d<sup>2</sup>), +3 (d<sup>3</sup>)', '+7 (d<sup>1</sup>), +6 (d<sup>2</sup>), +4 (d<sup>4</sup>), +3 (d<sup>5</sup>)', '+7 (d<sup>0</sup>), +6 (d<sup>2</sup>), +4 (d<sup>3</sup>), +3 (d<sup>4</sup>)'], '<p>Mn has 7 valence electrons (3d<sup>5</sup>4s<sup>2</sup>), so the d count of an Mn(n) ion is 7 - n: +7: 0; +6: 1; +4: 3; +3: 4.</p>', 'd count = 7 - oxidation state for Mn.');
mk(5, 'f-block', 'Which of the following statements about the f-block is INCORRECT?', 'All lanthanoids show a +2 oxidation state of comparable stability to +3', ['Ce<sup>4+</sup> is a strong oxidising agent', 'Actinoids show more oxidation states than lanthanoids', 'Ln<sup>3+</sup> radii decrease across the series'], '<p>+3 is the stable state of all lanthanoids; +2 is limited to ions that attain 4f<sup>7</sup> (Eu<sup>2+</sup>), 4f<sup>14</sup> (Yb<sup>2+</sup>) or 4f<sup>6</sup> (Sm<sup>2+</sup>). The other statements are correct.</p>');
mk(5, 'mixed', 'The enthalpy of atomisation of Zn is about 130 kJ/mol, while that of V is about 515 kJ/mol. The best explanation is that', 'V has several unpaired d electrons contributing to metallic bonding, but Zn has none', ['Zn has a larger nuclear charge', 'V is an f-block element', 'Zn has no s electrons'], '<p>The strength of metallic bonding depends on the number of unpaired electrons per atom that can be shared. V (3d<sup>3</sup>4s<sup>2</sup>) has 5 bonding electrons; Zn (3d<sup>10</sup>4s<sup>2</sup>) uses only the two 4s electrons, because d<sup>10</sup> is too stable to participate.</p>');
mk(5, 'alloys and steel', 'Cementite, Fe<sub>3</sub>C, found in steel, is best described as', 'an interstitial compound in which carbon atoms occupy voids of the iron lattice', ['an ionic carbide of Fe<sup>3+</sup>', 'a pure covalent network of iron and carbon', 'a mixture of iron and graphite with no bonding'], '<p>Small carbon atoms fit in octahedral voids of the close-packed iron structure. Such interstitial carbides make steel harder than pure iron.</p>');
mk(5, 'mixed', 'Ti<sup>3+</sup> in water appears purple while Ti<sup>4+</sup> compounds (e.g. TiO<sub>2</sub>) are white. The most complete explanation is that', 'Ti<sup>3+</sup> is d<sup>1</sup>, and its electron is promoted from t<sub>2g</sub> to e<sub>g</sub> by visible light, whereas Ti<sup>4+</sup> is d<sup>0</sup> with nothing to excite', ['Ti<sup>4+</sup> has unpaired electrons and Ti<sup>3+</sup> has none', 'both are d<sup>0</sup>, but Ti<sup>3+</sup> has a charge-transfer band', 'Ti<sup>3+</sup> is a larger ion than Ti<sup>4+</sup> and therefore coloured'], '<p>Colour from d-d transitions needs at least one d electron and an empty d orbital to go to. Ti<sup>3+</sup> (d<sup>1</sup>) satisfies this; Ti<sup>4+</sup> (d<sup>0</sup>) does not and is white (apart from charge transfer in the ultraviolet).</p>');
mk(5, 'mixed', 'E&deg;(Zn<sup>2+</sup>/Zn) = -0.76 V but E&deg;(Cu<sup>2+</sup>/Cu) = +0.34 V. Which energy term is mainly responsible for the difference from Zn to Cu?', 'the much larger sum of atomisation and ionisation enthalpies of Cu, not compensated by hydration', ['the hydration enthalpy of Zn<sup>2+</sup> being positive', 'Zn having no ionisation enthalpy', 'Cu being more electropositive'], '<p>E&deg; reflects the overall energy of M(s) &rarr; M<sup>2+</sup>(aq) + 2e<sup>-</sup>: atomisation + ionisation enthalpies (costs) minus hydration enthalpy (gain). For Cu the costs (&Delta;<sub>a</sub>H = 339, &Delta;<sub>i</sub>H<sub>1</sub> + &Delta;<sub>i</sub>H<sub>2</sub> = 2703 kJ/mol) are not repaid by hydration (-2121 kJ/mol), unlike Zn.</p>');
const groups = {
  m1: { title: 'Catalysts and processes', list1: ['A. Fe', 'B. V<sub>2</sub>O<sub>5</sub>', 'C. Ni (finely divided)', 'D. MnO<sub>2</sub>'], list2: ['p. synthesis of ammonia (Haber)', 'q. contact process (SO<sub>3</sub> formation)', 'r. hydrogenation of vegetable oils', 's. decomposition of KClO<sub>3</sub>'] },
  m2: { title: 'Aqueous ions and their colours', list1: ['A. Cu<sup>2+</sup>', 'B. Mn<sup>2+</sup>', 'C. Ni<sup>2+</sup>', 'D. Fe<sup>3+</sup>'], list2: ['p. blue', 'q. pale pink', 'r. green', 's. yellow-brown'] },
  m3: { title: 'Manganese compounds and oxidation states', list1: ['A. KMnO<sub>4</sub>', 'B. K<sub>2</sub>MnO<sub>4</sub>', 'C. MnO<sub>2</sub>', 'D. MnSO<sub>4</sub>'], list2: ['p. +2', 'q. +4', 'r. +6', 's. +7'] },
  m4: { title: 'Unusual oxidation states of lanthanoids', list1: ['A. Ce<sup>4+</sup>', 'B. Eu<sup>2+</sup>', 'C. Yb<sup>2+</sup>', 'D. Sm<sup>2+</sup>'], list2: ['p. 4f<sup>0</sup>', 'q. 4f<sup>7</sup>', 'r. 4f<sup>14</sup>', 's. 4f<sup>6</sup>'] },
  m5: { title: 'Minerals and composition', list1: ['A. Pyrolusite', 'B. Chromite', 'C. Haematite', 'D. Monazite'], list2: ['p. MnO<sub>2</sub>', 'q. FeCr<sub>2</sub>O<sub>4</sub>', 'r. Fe<sub>2</sub>O<sub>3</sub>', 's. lanthanoid (and thorium) phosphate'] },
  p1: { title: 'Permanganate titration of iron(II)', passage: '<p>A 20.0 mL sample of an Fe<sup>2+</sup> solution is acidified with dilute H<sub>2</sub>SO<sub>4</sub> and titrated with 0.0200 M KMnO<sub>4</sub>. It needs 25.0 mL of the permanganate to reach the end point.</p>' },
  p2: { title: 'A standard dichromate solution', passage: '<p>0.294 g of pure K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (M = 294 g/mol) is dissolved in water and made up to 100 mL. In acid it is reduced to Cr<sup>3+</sup>.</p>' },
  p3: { title: 'Lanthanoid contraction data', passage: '<p>The ionic radii of some lanthanoid ions are La<sup>3+</sup> 106 pm, Ce<sup>3+</sup> 103 pm, Gd<sup>3+</sup> 94 pm and Lu<sup>3+</sup> 85 pm. La is the first and Lu the last of the 15 elements La to Lu.</p>' },
};
// ---------- Templates ----------
const DIS = [ // couples: lower couple (reduction of the species to the metal/lower state), upper couple, n, equation
  { sp: 'Cu<sup>+</sup>', eq: '2Cu<sup>+</sup> &rarr; Cu<sup>2+</sup> + Cu', Er: 0.52, Eo: 0.15, n: 1, red: 'Cu<sup>+</sup>/Cu', ox: 'Cu<sup>2+</sup>/Cu<sup>+</sup>' },
  { sp: 'Au<sup>+</sup>', eq: '3Au<sup>+</sup> &rarr; Au<sup>3+</sup> + 2Au', Er: 1.69, Eo: 1.40, n: 2, red: 'Au<sup>+</sup>/Au', ox: 'Au<sup>3+</sup>/Au<sup>+</sup>' },
  { sp: 'Fe<sup>2+</sup>', eq: '3Fe<sup>2+</sup> &rarr; 2Fe<sup>3+</sup> + Fe', Er: -0.44, Eo: 0.77, n: 2, red: 'Fe<sup>2+</sup>/Fe', ox: 'Fe<sup>3+</sup>/Fe<sup>2+</sup>' },
  { sp: 'Hg<sub>2</sub><sup>2+</sup>', eq: 'Hg<sub>2</sub><sup>2+</sup> &rarr; Hg<sup>2+</sup> + Hg', Er: 0.79, Eo: 0.92, n: 1, red: 'Hg<sub>2</sub><sup>2+</sup>/Hg', ox: 'Hg<sup>2+</sup>/Hg<sub>2</sub><sup>2+</sup>' },
];
const REDS = [ // reducing agents oxidised by acidified permanganate: name, electrons lost per formula unit
  ['FeSO<sub>4</sub> (Fe<sup>2+</sup> &rarr; Fe<sup>3+</sup>)', 1], ['H<sub>2</sub>C<sub>2</sub>O<sub>4</sub> (oxalic acid &rarr; CO<sub>2</sub>)', 2], ['FeC<sub>2</sub>O<sub>4</sub> (ferrous oxalate)', 3], ['Na<sub>2</sub>SO<sub>3</sub> (sulphite &rarr; sulphate)', 2],
  ['H<sub>2</sub>O<sub>2</sub> (&rarr; O<sub>2</sub>)', 2], ['nitrite ion, NO<sub>2</sub><sup>-</sup> (&rarr; nitrate)', 2], ['SnCl<sub>2</sub> (Sn<sup>2+</sup> &rarr; Sn<sup>4+</sup>)', 2], ['KI (I<sup>-</sup> &rarr; I<sub>2</sub>, per I<sup>-</sup>)', 1],
];
const gens = [
  { id: 'df-g01', type: 'nat', level: 2, exams: EX[2], sub: 'unpaired electrons in atoms',
    make(rng) { const a = choose(rng, AT); const n = unpD(a.d) + (a.e === 1 ? 1 : 0); return { q: `How many unpaired electrons does a ground-state atom of ${a.s} (Z = ${a.Z}) have?`, answer: n, tol: 0, d: a.d, e: a.e, sol: `<p>${a.s}: ${cfgA(a)}.</p><p>3d: ${unpD(a.d)} unpaired${a.e === 1 ? '; 4s has one unpaired electron' : '; 4s<sup>2</sup> is paired'}. Total = <b>${n}</b>.</p>` }; },
    verify: (p) => (p.d <= 5 ? p.d : 10 - p.d) + (p.e === 1 ? 1 : 0) },
  { id: 'df-g02', type: 'nat', level: 2, exams: EX[2], sub: 'configuration of ions',
    make(rng) { const a = choose(rng, AT.filter((x) => x.s !== 'Zn' && x.s !== 'Sc')); const zmax = Math.min(3, a.d + a.e - 1); const z = int(rng, 1, zmax); const d = dOf(a, z);
      return { q: `How many electrons occupy the 3d subshell of ${ionF(a.s, z)}? (Z of ${a.s} = ${a.Z}.)`, answer: d, tol: 0, d0: a.d, e0: a.e, z, sol: `<p>${a.s}: ${cfgA(a)}. The 4s electrons are lost first, then 3d.</p><p>${ionF(a.s, z)} has ${a.d + a.e} - ${z} = <b>${d}</b> electrons in 3d.</p>` }; },
    verify: (p) => p.d0 + p.e0 - p.z },
  { id: 'df-g03', type: 'nat', level: 3, exams: EX[3], sub: 'magnetic moment',
    make(rng) { const a = choose(rng, AT.filter((x) => x.s !== 'Zn' && x.s !== 'Sc')); const z = int(rng, 2, Math.min(3, a.d + a.e - 1)); const d = dOf(a, z); const n = unpD(d);
      return { q: `Find the spin-only magnetic moment (BM) of ${ionF(a.s, z)} (Z of ${a.s} = ${a.Z}). Treat it as a free ion.`, answer: bm(n), tol: 0.02, unit: 'BM', d, sol: `<p>${ionF(a.s, z)}: 3d<sup>${d}</sup>, n = ${n} unpaired electron${n === 1 ? '' : 's'}.</p><p>&mu; = sqrt(${n} &times; ${n + 2}) = <b>${bm(n)} BM</b>.</p>` }; },
    verify: (p) => { const n = p.d <= 5 ? p.d : 10 - p.d; return Math.sqrt(n * (n + 2)); } },
  { id: 'df-g04', type: 'nat', level: 2, exams: EX[2], sub: 'highest oxidation state',
    make(rng) { const a = choose(rng, AT.filter((x) => ['Sc', 'Ti', 'V', 'Cr', 'Mn'].includes(x.s))); const ox = a.d + a.e; return { q: `What is the highest oxidation state shown by ${a.s} (Z = ${a.Z})? Assume all (n-1)d and ns electrons can be used.`, answer: ox, tol: 0, d: a.d, e: a.e, sol: `<p>${a.s}: ${cfgA(a)}. Highest state = 3d electrons + 4s electrons = ${a.d} + ${a.e} = <b>+${ox}</b>.</p>` }; },
    verify: (p) => p.d + p.e },
  { id: 'df-g05', type: 'nat', level: 2, exams: EX[2], sub: 'oxidation state',
    make(rng) { const o = choose(rng, OXS); return { q: `Find the oxidation state of ${o[1]} in ${o[0]}.`, answer: o[2], tol: 0, sol: `<p>Sum of oxidation states equals the overall charge: ${o[3]}.</p><p>${o[1]} is <b>+${o[2]}</b>.</p>` }; } },
  { id: 'df-g06', type: 'nat', level: 3, exams: EX[3], sub: 'lanthanoid ions',
    make(rng) { const s = choose(rng, LN); const n = f3(s); const u = unpF(n); return { q: `How many unpaired electrons are there in ${s}<sup>3+</sup> (atomic number ${57 + n}), counting 4f<sup>${n}</sup> by Hund&rsquo;s rule?`, answer: u, tol: 0, n, sol: `<p>${s}<sup>3+</sup> = [Xe]4f<sup>${n}</sup>. With 7 orbitals, electrons go in singly up to 7, then pair: unpaired = ${n <= 7 ? n : '14 - ' + n} = <b>${u}</b>.</p>` }; },
    verify: (p) => Math.min(p.n, 14 - p.n) },
  { id: 'df-g07', type: 'nat', level: 3, exams: EX[3], sub: 'magnetic moment of Ln ions',
    make(rng) { const s = choose(rng, LN.filter((x) => x !== 'La' && x !== 'Lu')); const n = f3(s); const u = unpF(n); return { q: `Using the spin-only formula, find the magnetic moment (BM) predicted for ${s}<sup>3+</sup> (4f<sup>${n}</sup>).`, answer: bm(u), tol: 0.02, unit: 'BM', u, sol: `<p>${s}<sup>3+</sup> has ${u} unpaired 4f electron${u === 1 ? '' : 's'}.</p><p>&mu; = sqrt(${u} &times; ${u + 2}) = <b>${bm(u)} BM</b> (the observed value differs because of orbital contribution).</p>` }; },
    verify: (p) => Math.sqrt(p.u * (p.u + 2)) },
  { id: 'df-g08', type: 'nat', level: 2, exams: EX[2], sub: 'equivalent mass',
    make(rng) { const c = choose(rng, [['KMnO<sub>4</sub> (M = 158) in acid, MnO<sub>4</sub><sup>-</sup> &rarr; Mn<sup>2+</sup>', 158, 5], ['KMnO<sub>4</sub> (M = 158) in neutral medium, &rarr; MnO<sub>2</sub>', 158, 3], ['KMnO<sub>4</sub> (M = 158) in strongly alkaline medium, &rarr; MnO<sub>4</sub><sup>2-</sup>', 158, 1], ['K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> (M = 294) in acid, &rarr; Cr<sup>3+</sup>', 294, 6]]); const eq = +(c[1] / c[2]).toFixed(2);
      return { q: `Find the equivalent mass of ${c[0]}.`, answer: eq, tol: 0.05, M: c[1], nf: c[2], sol: `<p>Equivalent mass = molar mass / n-factor, where n-factor is the number of electrons gained per formula unit (${c[2]}).</p><p>${c[1]}/${c[2]} = <b>${eq}</b>.</p>` }; },
    verify: (p) => p.M / p.nf },
  { id: 'df-g09', type: 'nat', level: 3, exams: EX[3], sub: 'permanganate titration',
    make(rng) { const M = choose(rng, [0.01, 0.02, 0.04]); const V = choose(rng, [10, 15, 20, 25]); const Vf = choose(rng, [10, 20, 25]); const cf = M * V * 5 / Vf;
      return { q: `${Vf} mL of an acidified Fe<sup>2+</sup> solution needs ${V} mL of ${M} M KMnO<sub>4</sub> to reach the end point. Find the molarity of Fe<sup>2+</sup> (mol/L).`, answer: +cf.toFixed(4), tol: Math.max(0.0005, cf * 0.01), unit: 'M', M, V, Vf, sol: `<p>MnO<sub>4</sub><sup>-</sup> + 5Fe<sup>2+</sup> + 8H<sup>+</sup> &rarr; Mn<sup>2+</sup> + 5Fe<sup>3+</sup> + 4H<sub>2</sub>O.</p><p>n(MnO<sub>4</sub><sup>-</sup>) = ${M} &times; ${V} = ${(M * V).toFixed(3)} mmol; n(Fe<sup>2+</sup>) = 5 &times; ${(M * V).toFixed(3)} = ${(M * V * 5).toFixed(3)} mmol.</p><p>Molarity = ${(M * V * 5).toFixed(3)}/${Vf} = <b>${cf.toFixed(4)} M</b>.</p>` }; },
    verify: (p) => p.M * p.V * 5 / p.Vf },
  { id: 'df-g10', type: 'nat', level: 3, exams: EX[3], sub: 'permanganate and oxalate',
    make(rng) { const M = choose(rng, [0.02, 0.04, 0.05]); const V = choose(rng, [10, 20, 25, 30]); const m = M * V / 1000 * 2.5 * 134;
      return { q: `In acid solution, ${V} mL of ${M} M KMnO<sub>4</sub> exactly oxidises the oxalate in a sample of sodium oxalate, Na<sub>2</sub>C<sub>2</sub>O<sub>4</sub> (M = 134). Find the mass of sodium oxalate in grams.`, answer: +m.toFixed(4), tol: Math.max(0.002, m * 0.01), unit: 'g', M, V, sol: `<p>2MnO<sub>4</sub><sup>-</sup> + 5C<sub>2</sub>O<sub>4</sub><sup>2-</sup> + 16H<sup>+</sup> &rarr; 2Mn<sup>2+</sup> + 10CO<sub>2</sub> + 8H<sub>2</sub>O.</p><p>n(MnO<sub>4</sub><sup>-</sup>) = ${M} &times; ${V}/1000 = ${(M * V / 1000).toFixed(5)} mol; n(oxalate) = 5/2 &times; that = ${(M * V / 1000 * 2.5).toFixed(5)} mol.</p><p>Mass = ${(M * V / 1000 * 2.5).toFixed(5)} &times; 134 = <b>${m.toFixed(4)} g</b>.</p>` }; },
    verify: (p) => p.M * p.V / 1000 * (5 / 2) * 134 },
  { id: 'df-g11', type: 'nat', level: 3, exams: EX[3], sub: 'dichromate titration',
    make(rng) { const M = choose(rng, [0.01, 0.02, 0.05]); const C = choose(rng, [0.05, 0.1, 0.2]); const Vf = choose(rng, [10, 20, 25]); const V = C * Vf / (6 * M);
      return { q: `What volume (mL) of ${M} M K<sub>2</sub>Cr<sub>2</sub>O<sub>7</sub> is needed in acid to oxidise ${Vf} mL of ${C} M FeSO<sub>4</sub> completely?`, answer: +V.toFixed(2), tol: Math.max(0.05, V * 0.01), unit: 'mL', M, C, Vf, sol: `<p>Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup> + 6Fe<sup>2+</sup> + 14H<sup>+</sup> &rarr; 2Cr<sup>3+</sup> + 6Fe<sup>3+</sup> + 7H<sub>2</sub>O.</p><p>n(Fe<sup>2+</sup>) = ${C} &times; ${Vf} = ${(C * Vf).toFixed(2)} mmol; n(Cr<sub>2</sub>O<sub>7</sub><sup>2-</sup>) = ${(C * Vf / 6).toFixed(4)} mmol.</p><p>V = ${(C * Vf / 6).toFixed(4)}/${M} = <b>${V.toFixed(2)} mL</b>.</p>` }; },
    verify: (p) => p.C * p.Vf / 6 / p.M },
  { id: 'df-g12', type: 'nat', level: 4, exams: EX[4], sub: 'disproportionation',
    make(rng) { const d = choose(rng, DIS); const E = +(d.Er - d.Eo).toFixed(2); return { q: `E&deg;(${d.red}) = ${d.Er} V and E&deg;(${d.ox}) = ${d.Eo} V. Find E&deg;cell (V) for the reaction ${d.eq}.`, answer: E, tol: 0.01, unit: 'V', Er: d.Er, Eo: d.Eo, sol: `<p>The species is reduced by the first couple (cathode, ${d.Er} V) and oxidised by the second (anode, ${d.Eo} V).</p><p>E&deg;cell = ${d.Er} - (${d.Eo}) = <b>${E} V</b>${E > 0 ? ', positive, so it disproportionates.' : ', negative, so it does NOT disproportionate.'}</p>` }; },
    verify: (p) => p.Er - p.Eo },
  { id: 'df-g13', type: 'nat', level: 4, exams: EX[4], sub: 'disproportionation constant',
    make(rng) { const d = choose(rng, DIS.filter((x) => x.Er - x.Eo > 0)); const E = d.Er - d.Eo; const lk = d.n * E / 0.059; return { q: `For ${d.eq} (n = ${d.n}) the standard emf is ${E.toFixed(2)} V. Find log K at 298 K. (0.059 V)`, answer: +lk.toFixed(2), tol: 0.05, n: d.n, E: +E.toFixed(2), sol: `<p>log K = nE&deg;/0.059 = ${d.n} &times; ${E.toFixed(2)}/0.059 = <b>${lk.toFixed(2)}</b>.</p>` }; },
    verify: (p) => p.n * p.E / 0.059 },
  { id: 'df-g14', type: 'nat', level: 4, exams: EX[4], sub: 'electrolytic preparation of KMnO4',
    make(rng) { const I = choose(rng, [2, 4, 5, 10]); const t = 965 * pick(rng, 1, 6, 1); const m = I * t / 96500 * 158;
      return { q: `K<sub>2</sub>MnO<sub>4</sub> is oxidised to KMnO<sub>4</sub> at the anode (MnO<sub>4</sub><sup>2-</sup> &rarr; MnO<sub>4</sub><sup>-</sup> + e<sup>-</sup>). How many grams of KMnO<sub>4</sub> (M = 158) form when ${I} A passes for ${t} s with 100% current efficiency? (F = 96500 C/mol)`, answer: +m.toFixed(2), tol: Math.max(0.05, m * 0.01), unit: 'g', I, t, sol: `<p>Q = ${I} &times; ${t} = ${I * t} C = ${(I * t / 96500).toFixed(3)} mol e<sup>-</sup>. One electron per ion, so ${(I * t / 96500).toFixed(3)} mol KMnO<sub>4</sub>.</p><p>Mass = ${(I * t / 96500).toFixed(3)} &times; 158 = <b>${m.toFixed(2)} g</b>.</p>` }; },
    verify: (p) => p.I * p.t * 158 / 96500 },
  { id: 'df-g15', type: 'nat', level: 3, exams: EX[3], sub: 'lanthanoid contraction',
    make(rng) { const r1 = pick(rng, 100, 118, 1); const r2 = pick(rng, 82, 95, 1); const p = (r1 - r2) / r1 * 100; return { q: `The ionic radius of Ln<sup>3+</sup> falls from ${r1} pm (first lanthanoid) to ${r2} pm (last lanthanoid). Find the percentage decrease.`, answer: +p.toFixed(1), tol: 0.1, unit: '%', r1, r2, sol: `<p>Decrease = ${r1} - ${r2} = ${r1 - r2} pm.</p><p>Percentage = ${r1 - r2}/${r1} &times; 100 = <b>${p.toFixed(1)}%</b>.</p>` }; },
    verify: (p) => (p.r1 - p.r2) * 100 / p.r1 },
  { id: 'df-g16', type: 'nat', level: 3, exams: EX[3], sub: 'preparation of KMnO4',
    make(rng) { const m = choose(rng, [8.7, 17.4, 26.1, 43.5]); const route = choose(rng, ['electrolytic', 'acid']); const f = route === 'electrolytic' ? 1 : 2 / 3; const mass = m / 87 * f * 158;
      return { q: `${m} g of MnO<sub>2</sub> (M = 87) is fused with KOH and air to give K<sub>2</sub>MnO<sub>4</sub>, which is then converted to KMnO<sub>4</sub> by ${route === 'electrolytic' ? 'electrolytic oxidation (no loss of manganese)' : 'disproportionation in acid (3MnO<sub>4</sub><sup>2-</sup> + 4H<sup>+</sup> &rarr; 2MnO<sub>4</sub><sup>-</sup> + MnO<sub>2</sub> + 2H<sub>2</sub>O)'}. Find the mass of KMnO<sub>4</sub> (M = 158) formed, in g (100% yield at each step).`, answer: +mass.toFixed(2), tol: Math.max(0.05, mass * 0.01), unit: 'g', m, f, sol: `<p>n(MnO<sub>2</sub>) = ${m}/87 = ${(m / 87).toFixed(3)} mol = n(K<sub>2</sub>MnO<sub>4</sub>).</p><p>${route === 'electrolytic' ? 'All the Mn becomes MnO<sub>4</sub><sup>-</sup>.' : 'Only 2 of every 3 Mn atoms become MnO<sub>4</sub><sup>-</sup> (the rest is MnO<sub>2</sub>), a factor 2/3.'} n(KMnO<sub>4</sub>) = ${(m / 87 * f).toFixed(3)} mol.</p><p>Mass = ${(m / 87 * f).toFixed(3)} &times; 158 = <b>${mass.toFixed(2)} g</b>.</p>` }; },
    verify: (p) => p.m / 87 * p.f * 158 },
  { id: 'df-g17', type: 'nat', level: 4, exams: EX[4], sub: 'redox stoichiometry',
    make(rng) { const r = choose(rng, REDS); const n = choose(rng, [1, 2, 3, 5, 10]); const mol = n * r[1] / 5;
      return { q: `How many moles of KMnO<sub>4</sub> are needed in acid medium (MnO<sub>4</sub><sup>-</sup> &rarr; Mn<sup>2+</sup>) to oxidise ${n} mol of ${r[0]} completely?`, answer: +mol.toFixed(3), tol: Math.max(0.005, mol * 0.01), unit: 'mol', n, e: r[1], sol: `<p>Electrons lost per formula unit: ${r[1]}. Total electrons = ${n} &times; ${r[1]} = ${n * r[1]} mol. Each MnO<sub>4</sub><sup>-</sup> accepts 5 electrons.</p><p>n(KMnO<sub>4</sub>) = ${n * r[1]}/5 = <b>${mol.toFixed(3)} mol</b>.</p>` }; },
    verify: (p) => p.n * p.e / 5 },
  { id: 'df-g18', type: 'nat', level: 2, exams: EX[2], sub: 'lanthanoids',
    make(rng) { const Z = int(rng, 58, 71); const el = LN[Z - 57]; return { q: `The lanthanoid with atomic number ${Z} is ${el}. How many 4f electrons does the ion ${el}<sup>3+</sup> have? (La, Z = 57, has 4f<sup>0</sup> as La<sup>3+</sup>.)`, answer: Z - 57, tol: 0, Z, sol: `<p>The 4f subshell fills one electron per element after La. Ln<sup>3+</sup> has 4f<sup>(Z - 57)</sup>: ${Z} - 57 = <b>${Z - 57}</b>.</p>` }; },
    verify: (p) => p.Z - 57 },
  { id: 'df-g19', type: 'mcq', level: 3, exams: EXM[3], sub: 'magnetic moment comparison',
    make(rng) { const pool = [['Ti', 3, 1], ['V', 3, 2], ['Cr', 3, 3], ['Fe', 2, 4], ['Mn', 2, 5]]; const idx = [0, 1, 2, 3, 4]; for (let i = idx.length - 1; i > 0; i--) { const j = int(rng, 0, i); [idx[i], idx[j]] = [idx[j], idx[i]]; } const pick4 = idx.slice(0, 4).map((i) => pool[i]); const best = pick4.reduce((a, b) => (b[2] > a[2] ? b : a));
      const r = shuffleOpts(rng, ionF(best[0], best[1]), pick4.filter((x) => x !== best).map((x) => ionF(x[0], x[1])));
      return { q: 'Which of these free ions has the largest spin-only magnetic moment?', options: r.options, answer: r.answer, sol: `<p>Unpaired electrons: ${pick4.map((x) => `${ionF(x[0], x[1])} = ${x[2]}`).join('; ')}.</p><p>The largest is <b>${ionF(best[0], best[1])}</b> with ${best[2]} unpaired electrons (${bm(best[2])} BM).</p>` }; } },
];

export default {
  topic: 'd-f-block',
  groups,
  items: L.map((it, i) => ({ id: `df-${String(i + 1).padStart(3, '0')}`, ...it })),
  gens,
};
